/**
 * `.reqseq/local.yaml` next to `reqseq-workspace.yaml`: settings of one person on one machine. The file is not committed (add `.reqseq/` to `.gitignore`). It overrides where a repository of the workspace lies locally. Faulty content is reported as a warning and ignored.
 * Schema: `schemas/workspace-local.schema.json#`.
 */
export interface WorkspaceLocalFile {
  /** Version of this file format. */
  readonly "reqseq-local": 1;
  /** Per repository name of the workspace file: where it lies on this machine. */
  readonly repositories?: Readonly<Record<string, {
    /** Absolute path, or relative to the main repository (the folder with `reqseq-workspace.yaml`). No `~` expansion. */
    readonly path: string;
  }>>;
}

/**
 * `reqseq-workspace.yaml` in the root of the main repository (D-041, SR-004). Names the repositories that belong together. Everyone has locally only those they may access; missing ones are shown as not available (N-041, SR-004 AK3). A single-repository workspace lists only itself (SR-004 AK2).
 * Schema: `schemas/workspace.schema.json#`.
 */
export interface WorkspaceFile {
  /** Version of this file format. */
  readonly "reqseq-workspace": 1;
  /** Name of the workspace. */
  readonly name: string;
  /** The entry with `main: true` is the repository that holds this file. With two or more repositories exactly one has `main: true`; a single repository is the main one even without it. Names are unique (checked by ReqSeq; JSON Schema cannot express it). */
  readonly repositories: readonly WorkspaceRepository[];
  /** Where the metamodel lies: a folder in one of the repositories, the main one or its own (D-021, SR-011, SR-018). */
  readonly metamodel: WorkspaceLocation;
  /** Folders with evidence records (Markdown) and JUnit XML files (SR-028 AK1). They may be in repositories of other tools. */
  readonly evidence?: readonly WorkspaceLocation[];
  /** Where new baseline files are written. Default: folder `baselines` in the main repository. */
  readonly baselines?: WorkspaceLocation;
  /** Where saved filters are written (SR-070). Default: folder `filters` in the main repository. */
  readonly filters?: WorkspaceLocation;
  /** Where ReqIF mapping files are written (SR-054). Default: folder `reqif` in the main repository. */
  readonly mappings?: WorkspaceLocation;
  /** Glob patterns of paths that are never read as elements, relative to each repository and anchored at its root, with `/` as separator (no `\`, no `//`). `*` matches any characters within one name, `?` one character, `**` as a whole name any number of names, including none; every other character is literal (no `[...]`, no `{a,b}`). Case-sensitive on every OS; wildcards match names starting with `.`. A leading `/` or `./` and a trailing `/` are dropped; `x/**` matches folder `x` itself, so it is skipped as a whole. Example: `website/**`, `**\/*.draft.md`. `.git` and `node_modules` are always ignored. */
  readonly ignore?: readonly string[];
}

/** Schema: `schemas/workspace.schema.json#/$defs/repository`. */
export interface WorkspaceRepository {
  /** Name of the repository in the workspace: lower case letters, digits, `.`, `_` and `-`. */
  readonly name: string;
  /** Address of the repository on the Git server. Informational: ReqSeq never clones or fetches (D-036). */
  readonly url: string;
  /** Expected local location relative to the main repository, with `/` as separator. Default `../<name>`; always `.` for the main repository. Absolute paths and `\` are warned about; an absolute path is ignored, and so is one that leaves the folder holding the main repository or passes a link out of a repository (it can lead to a network share); there is no `~` expansion. A person can override it in the untracked file `.reqseq/local.yaml`. */
  readonly path?: string;
  /** The repository that holds this file. */
  readonly main?: boolean;
  /** The repository does not know the variants of the workspace (SR-173): an evidence record without `variant` for one of its elements counts in the core and in every variant the element applies in (the view rule, SR-047 AK3). Without the mark such a record counts only in the core (D-026). Shared: `.reqseq/local.yaml` cannot change it. An older ReqSeq rejects a workspace file with it (`file.faulty`). */
  readonly "variant-independent"?: boolean;
}

/** Schema: `schemas/workspace.schema.json#/$defs/mainRepository`. */
export interface WorkspaceMainRepository {
  /** The repository that holds this file. */
  readonly main: true;
  readonly [key: string]: unknown;
}

/** Schema: `schemas/workspace.schema.json#/$defs/location`. */
export interface WorkspaceLocation {
  /** Workspace name of the repository. */
  readonly repository: string;
  readonly path: RelativePath;
}

/**
 * Command catalog
 * Schema: `schemas/commands/catalog.meta.schema.json#`.
 */
export interface CommandCatalog {
  readonly $schema?: string;
  readonly "reqseq-catalog": 1;
  readonly description?: string;
  readonly commands: readonly {
    /** group.action; CLI `reqseq group action`, API `POST /v1/commands/group.action`, MCP tool `group_action`. */
    readonly name: string;
    /** The name of the command for people, English, sentence case, unique in the catalog: what the app's command prompt offers (SR-108, SR-073 AK2) and the MCP tool `title`. When an app action does the same, the title is the action's name, so the prompt lists it once. Free of delete words except for relations (D-045). */
    readonly title: string;
    /** What the command does and what for, in one or two sentences in the user's words: the command reference, its index, `--help`, the MCP tool description and the OpenAPI summary show it. At most 50 words, counted as the text split at white space (`catalog-checks.mjs`, #1252). */
    readonly summary: string;
    /** What a user needs to know beyond the summary: rules, cases and limits of the command. Shown on the command's reference page below the summary, not in the index, `--help` or the MCP tool list (#1252). Implementation notes belong in the block files of `packages/core/docs/`. */
    readonly details?: string;
    /** No command writes to Git (D-036). No command deletes elements (D-045). */
    readonly effect: "read" | "write-files";
    /** Whether a `write-files` command runs while the workspace is read-only (a missing or faulty metamodel, SR-011 AK3): `refuse` gives `workspace.read-only` before the command runs, `allow` runs it (`workspace.init`, which creates the workspace). Required for `write-files`, not allowed for `read` (reads always run). Each command's SR decides; until then `refuse` (ADR-0002 rule 5, ThomasBirkmaier/ReqSeq-archive#142). */
    readonly whileReadOnly?: "refuse" | "allow";
    /** Why the command has its `whileReadOnly` value, in one line for the people who change it. Required with `whileReadOnly`. */
    readonly whileReadOnlyReason?: string;
    /** The stage of the delivery plan in which the command is built. */
    readonly stage: number;
    readonly implements: readonly string[];
    /** How a command prompt asks for the input (SR-108 AK4): every top-level property of `input` exactly once, the required ones first, in the order they are asked. `complete` says where the values to offer come from (a closed list; the app maps each source to one read command of core and decides nothing about what is allowed; `folder` and `file` map to `workspace.listFolder`, the one read command made for completion, because only core reads the file system). `of` names an earlier field the source depends on. Without it, the nearest earlier field of the fitting source: an `element` or `relationTarget` field for status, invalidStatus, relationKind, hint, property and relation (relation also a `relation` field); a `relationKind` field for relationTarget; a `property` field for value. With no such field, status, invalidStatus, relationKind, hint and property give every value of the metamodel or the workspace; relationTarget, relation and value need one. `validate-schemas.mjs` checks the coverage, the order and `of` (`catalog-checks.mjs`). */
    readonly arguments: readonly {
      /** A top-level property of `input`. */
      readonly field: string;
      /** element: elements found by element.search. type: types of the metamodel. status: statuses of the type of the element in `of` (without it, every status of the metamodel). invalidStatus: of those, the ones the metamodel marks invalid. relationKind: kinds that relation.options allows from the element in `of` (without it, every relation kind of the metamodel). relationTarget: elements of the target types of the kind in `of` (element.search with selection.where.type). relation: with `of` an element field, the kinds of the existing relations of that element; with `of` a relation field (the kind asked before), the targets of the relations of that kind (relation.remove: source, kind, target). property: properties of the type of the element in `of` (every property of the metamodel without it). value: the values the metamodel fixes for the property in `of`. hint: open hints of the element in `of` (without it, every open hint). filter: saved filters. baseline: baselines (baseline.list). view: `core` and the variants of the workspace (element.list of the types with the meaning `variant`). repository: repositories of the workspace. selection: the selection of the list shown. choice: the inline `enum` of the property. folder: a `localPath` field that names a folder, file: one that names a file; both completed with the entries of the typed folder (workspace.listFolder, files only for file), and every `localPath` field has one of them (`catalog-checks.mjs`). text, number, boolean: typed free input. json: any other object or mixed field, typed as JSON and checked by core. */
      readonly complete:
        | "element"
        | "type"
        | "status"
        | "invalidStatus"
        | "relationKind"
        | "relationTarget"
        | "relation"
        | "property"
        | "value"
        | "hint"
        | "filter"
        | "baseline"
        | "view"
        | "repository"
        | "selection"
        | "choice"
        | "folder"
        | "file"
        | "text"
        | "number"
        | "boolean"
        | "json";
      /** An earlier field of `arguments`. */
      readonly of?: string;
      /** Earlier optional fields a value of this field takes the place of: the prompt leaves them out of the input when this field has a value other than `false`, so they only said what it offers. `hint.confirm`: hints chosen at `hintIds` confirm only those, not every hint `ref`, `target` and `kind` select (#291); `all` yes confirms those of the workspace, not those of the shown element as `ref` (#644). `catalog-checks.mjs` checks the fields. */
      readonly replaces?: readonly string[];
      /** Name of the CLI flag, without `--`, when it is not the field name in kebab-case (ADR-0009): `element.create` takes its `properties` as `--set key=value`, as `element.update` takes `set`. Not the name of another field's flag, nor of a common option (`validate-schemas.mjs`, `catalog-checks.mjs`). */
      readonly flag?: string;
    }[];
    readonly input: Readonly<Record<string, unknown>>;
    /** The command also gives its output as JSON Lines (one compact JSON object and LF per line, UTF-8): the CLI with `--jsonl`, the API with `Accept: application/x-ndjson` (ADR-0009). Each line is the listed `fields` of the output, then one item of `items`; the other top-level fields are not in the lines. MCP and the app keep the JSON object (ADR-0002 rule 3, #319). */
    readonly jsonLines?: {
      /** A top-level array of `output`: one line per item. */
      readonly items: string;
      /** Top-level fields of `output` that every line carries before the keys of its item, in this order; a field the output leaves out is left out of the lines too. None is an array or a property of the item schema (`catalog-checks.mjs`). */
      readonly fields: readonly string[];
    };
    /** Outputs are JSON objects and say so at the root, also next to a `$ref`: MCP needs `type: object` at the root of an output schema (ADR-0009). */
    readonly output: {
      readonly type: "object";
      readonly [key: string]: unknown;
    };
  }[];
}

/**
 * Input of `workspace.init` as `run` gets it: validated, properties with a `default` filled in. Create a workspace with the standard model in a folder, which is created when only it is missing. Adds `*.reqseq-tmp` (temp files of an interrupted write) to the folder's `.gitignore`.
 * Schema: `schemas/commands/workspace.init.json input`.
 */
export interface WorkspaceInitInput {
  /** Folder of the workspace, created when only it is missing; must not contain reqseq-workspace.yaml or the metamodel file. */
  readonly path: LocalPath;
  /** Name of the workspace, written to reqseq-workspace.yaml. */
  readonly name: string;
  /** Where the metamodel lies. Default: the folder `metamodel` in the main repository, where the standard model is written. */
  readonly metamodel?: {
    /** Workspace name of the repository of the metamodel. Default: the main repository. */
    readonly repository?: string;
    /** Folder of the metamodel, relative to that repository. Default: `metamodel`. */
    readonly path?: string;
  };
}

/**
 * Output of `workspace.init`. Create a workspace with the standard model in a folder, which is created when only it is missing. Adds `*.reqseq-tmp` (temp files of an interrupted write) to the folder's `.gitignore`.
 * Schema: `schemas/commands/workspace.init.json output`.
 */
export interface WorkspaceInitOutput {
  readonly files: readonly string[];
  readonly problems?: readonly Problem[];
}

/**
 * Input of `workspace.status` as `run` gets it: validated, properties with a `default` filled in. Repositories of the workspace, which are available and which are variant-independent, where the metamodel comes from, the evidence locations and which are read, read-only state.
 * Schema: `schemas/commands/workspace.status.json input`.
 */
export type WorkspaceStatusInput = Readonly<Record<string, never>>;

/**
 * Output of `workspace.status`. Repositories of the workspace, which are available and which are variant-independent, where the metamodel comes from, the evidence locations and which are read, read-only state.
 * Schema: `schemas/commands/workspace.status.json output`.
 */
export interface WorkspaceStatusOutput {
  /** Name of the workspace, from reqseq-workspace.yaml. */
  readonly name: string;
  /** The repositories of the workspace file, in its order. */
  readonly repositories: readonly {
    /** Workspace name of the repository. */
    readonly name: string;
    /** The repository is on this machine. */
    readonly available: boolean;
    /** Where the repository lies, as configured: from `.reqseq/local.yaml`, else from the workspace file. */
    readonly path?: string;
    readonly commit?: Commit;
    /** The workspace file marks the repository variant-independent (SR-173): a record without variant for one of its elements counts in every view the element applies in. Left out without the mark. */
    readonly variantIndependent?: true;
    /** ReqSeq cannot write the repository folder itself (read-only file system or no write permission). Reading works as usual and the workspace stays writable; writes into this repository are refused with file.read-only. Rights on the Git server are not visible here (D-016, D-024). Only for available repositories; left out where the operating system cannot tell (Windows). */
    readonly readOnly?: boolean;
  }[];
  /** Where the metamodel comes from. */
  readonly metamodel: {
    /** Workspace name of the repository of the metamodel. */
    readonly repository: string;
    /** Folder of the metamodel, relative to that repository. */
    readonly path: string;
    /** The metamodel was read without errors. */
    readonly valid: boolean;
  };
  /** The `evidence` locations of the workspace file, in its order, as written (#625). Empty without the key. */
  readonly evidence: readonly {
    /** Workspace name of the repository of the evidence location. */
    readonly repository: string;
    readonly path: RelativePath;
    /** ReqSeq reads the folder for evidence: its repository is available, it exists and the reading rules do not skip it (a link, `.git`, `node_modules`, an `ignore` glob, another or a nested repository). `workspace check` says why not. */
    readonly available: boolean;
  }[];
  /** The workspace opens read-only because its metamodel is missing or faulty: nothing can be written. */
  readonly readOnly: boolean;
  readonly problems?: readonly Problem[];
}

/**
 * Input of `workspace.check` as `run` gets it: validated, properties with a `default` filled in. Check the whole workspace, or only what changed, against the metamodel and list every problem found. ok is false, and the CLI exits 1, on findings at or above failOn (default error).
 * Schema: `schemas/commands/workspace.check.json input`.
 */
export interface WorkspaceCheckInput {
  /** Restrict the check to the elements in these files and their targets (SR-092). A file must lie in a repository of the workspace and be no folder; deleted and non-element files add nothing. With changedSince, both count. To cover deleted elements, use changedSince: a deleted file named only in changedFiles adds no old UUID. */
  readonly changedFiles?: readonly LocalPath[];
  /** Git revision, e.g. the target commit of a merge request: restrict the check to the elements whose files (or embedded images) in the working copy differ from it, untracked files included, and their targets (SR-092). Looked up in every repository of the workspace; a repository without it, or without Git, adds nothing and gets an info problem (git.revision-missing, git.unavailable). The relations to an element file deleted since, or whose UUID changed, are kept. Error git.commit-not-found (CLI exit code 4) when no repository has it. */
  readonly changedSince?: string;
  /** Lowest severity of the problems shown; does not change ok or the exit code. Findings left out are counted in hidden. */
  readonly severity: "error" | "warning" | "info";
  /** Lowest severity of a finding that makes ok false (CLI exit code 1), shown or not; independent of severity. With the default, warnings and info never fail the check. */
  readonly failOn: "error" | "warning" | "info";
}

/**
 * Output of `workspace.check`. Check the whole workspace, or only what changed, against the metamodel and list every problem found. ok is false, and the CLI exits 1, on findings at or above failOn (default error).
 * Schema: `schemas/commands/workspace.check.json output`.
 */
export interface WorkspaceCheckOutput {
  /** False when the workspace has a finding at or above failOn, shown or not (CLI exit code 1, ADR-0009). In a restricted check, of the findings the restriction keeps. */
  readonly ok: boolean;
  readonly problems: readonly Problem[];
  /** The findings that severity leaves out of problems, by severity; only when it leaves out at least one, so that no problems shown does not read as no findings. */
  readonly hidden?: {
    /** The severity given: the findings counted are below it. */
    readonly below: "error" | "warning";
    /** Warnings left out. */
    readonly warning: number;
    /** Infos left out. */
    readonly info: number;
  };
  /** Number of elements checked: all of the workspace, or in a restricted check the changed elements and their targets (SR-092). */
  readonly checkedElements?: number;
  /** Time the check took in milliseconds. Not given yet: it differs between calls, and the cross-access test compares outputs (SR-080 AK2). */
  readonly durationMs?: number;
}

/**
 * Input of `workspace.activity` as `run` gets it: validated, properties with a `default` filled in. The element read or changed last through the local API or the MCP server on this working copy: which access, command and effect, when, and the element (UUID, repository); null when none is recorded.
 * Schema: `schemas/commands/workspace.activity.json input`.
 */
export type WorkspaceActivityInput = Readonly<Record<string, never>>;

/**
 * Output of `workspace.activity`. The element read or changed last through the local API or the MCP server on this working copy: which access, command and effect, when, and the element (UUID, repository); null when none is recorded.
 * Schema: `schemas/commands/workspace.activity.json output`.
 */
export interface WorkspaceActivityOutput {
  /** The last call through the API or the MCP server that named one element (the element reference it was given, or else the one element file a write wrote), as an API or MCP process of this copy recorded it in the cache folder of the copy (ADR-0008). null when there is none, the copy has no usable cache folder, or the record cannot be read. Calls of the command line and of the app are not recorded. */
  readonly activity: ActivityAccess | null;
}

/**
 * Input of `workspace.recent` as `run` gets it: validated, properties with a `default` filled in. The workspaces the app opened last, the most recent first (at most 20): the root of each, when it was opened, and whether the root still holds reqseq-workspace.yaml. The list belongs to the user, not to a workspace, so every access gives the same list from any folder.
 * Schema: `schemas/commands/workspace.recent.json input`.
 */
export type WorkspaceRecentInput = Readonly<Record<string, never>>;

/**
 * Output of `workspace.recent`. The workspaces the app opened last, the most recent first (at most 20): the root of each, when it was opened, and whether the root still holds reqseq-workspace.yaml. The list belongs to the user, not to a workspace, so every access gives the same list from any folder.
 * Schema: `schemas/commands/workspace.recent.json output`.
 */
export interface WorkspaceRecentOutput {
  /** The workspaces the app opened last, the most recent first, as the app's core process recorded them in `<OS cache>/reqseq/recent-workspaces.json` (ADR-0008). Empty when none is recorded or the list cannot be read. Only the app records; the command line, the API and the MCP server only read the list. */
  readonly workspaces: readonly {
    /** The absolute path of the workspace root as the app opened it last (the folder that holds reqseq-workspace.yaml). */
    readonly root: string;
    /** When the app opened it last. */
    readonly opened: IsoDateTime;
    /** Whether `<root>/reqseq-workspace.yaml` is a file now: the root itself, never a folder above it. A root without an answer within 1 s (a share that does not answer) counts as false; while earlier checks of this process still hang (a long-running API or MCP server), every root may count as false. */
    readonly exists: boolean;
  }[];
}

/**
 * Input of `workspace.listFolder` as `run` gets it: validated, properties with a `default` filled in. The folders and links, and on request the files, in the folder of a typed path, for completing a path while it is typed.
 * Schema: `schemas/commands/workspace.listFolder.json input`.
 */
export interface WorkspaceListFolderInput {
  /** The typed path, up to the name being typed (`~/pro`, `out/`, `C:\Work\sp`). A plain text, not a `localPath`: it is taken as typed, with its separator at the end. */
  readonly path: string;
  /** Also list the files (for an argument that takes a file); folders and links are always listed. */
  readonly files: boolean;
  /** Take only an absolute path, with `~` and `~/…` for the home folder on every access ("Open workspace", SR-131); without it the path is resolved as the commands of the access resolve a path argument: `~` is the home folder in the app only. */
  readonly absolute: boolean;
}

/**
 * Output of `workspace.listFolder`. The folders and links, and on request the files, in the folder of a typed path, for completing a path while it is typed.
 * Schema: `schemas/commands/workspace.listFolder.json output`.
 */
export interface WorkspaceListFolderOutput {
  /** The folder listed, absolute and normalised, without a separator at its end except at the root. Missing when the path is `invalid`. */
  readonly folder?: string;
  /** The typed name: the text after the last separator. Names that start with "." are listed only when it starts with ".". */
  readonly name: string;
  /** The entries, folders and links first, then files, each by the code units of the NFC form of the name. Other entries (sockets, devices) are left out. Empty with a `problem`. */
  readonly entries: readonly {
    /** The name as the file system spells it. */
    readonly name: string;
    /** folder, file, or link: a symbolic link, and on Windows any reparse point (junctions, OneDrive and Cloud Files placeholders, deduplicated files, app execution aliases); its target is not looked at. */
    readonly kind: "folder" | "file" | "link";
  }[];
  /** Why there are no entries: the folder does not exist (`missing`), cannot be read or gave no answer within 1 s (`unreadable`, also when the path names a file), or the path is refused by its text (`invalid`). */
  readonly problem?: "missing" | "unreadable" | "invalid";
  /** The folder has more than 50,000 matching entries; folders and links come first. */
  readonly truncated?: true;
}

/**
 * Input of `tool.info` as `run` gets it: validated, properties with a `default` filled in. Version and build of ReqSeq and its parts, the open workspace, the licence notices and where the documentation and the releases are. Reads only and opens no network connection.
 * Schema: `schemas/commands/tool.info.json input`.
 */
export type ToolInfoInput = Readonly<Record<string, never>>;

/**
 * Output of `tool.info`. Version and build of ReqSeq and its parts, the open workspace, the licence notices and where the documentation and the releases are. Reads only and opens no network connection.
 * Schema: `schemas/commands/tool.info.json output`.
 */
export interface ToolInfoOutput {
  /** The versions of the app, the command line and the MCP server. One delivery ships all three with the version of the delivery. */
  readonly versions: {
    /** Version of the app. */
    readonly app: string;
    /** Version of the command line. */
    readonly cli: string;
    /** Version of the MCP server. */
    readonly mcp: string;
  };
  /** The build of ReqSeq that runs. */
  readonly build: {
    /** The commit the delivery was built from. Left out in a build from a checkout. */
    readonly commit?: Commit;
    /** The build date: the date of that commit. Left out in a build from a checkout. */
    readonly date?: IsoDateTime;
    /** Built from a checkout, not delivered: commit and date are unknown. Left out in a delivery. */
    readonly development?: true;
    /** The operating system as Node names it (`darwin`, `linux`, `win32`). */
    readonly platform: string;
    /** The processor architecture as Node names it (`arm64`, `x64`). */
    readonly arch: string;
  };
  /** The runtime of the process. The delivered command line, API and MCP server run on the Electron of the app, so a delivery gives the same values in every access. */
  readonly runtime: {
    /** Left out when ReqSeq does not run on Electron (a command line on its own Node). */
    readonly electron?: string;
    /** Version of Node. */
    readonly node: string;
    /** The Chromium of the Electron ReqSeq runs on. Left out without Electron. */
    readonly chromium?: string;
  };
  /** The open workspace. */
  readonly workspace: {
    /** The absolute path of the workspace root, the folder with reqseq-workspace.yaml. */
    readonly path: string;
    /** Name of the workspace, from reqseq-workspace.yaml. */
    readonly name: string;
    /** The workspace names of its repositories, in the order of the workspace file. */
    readonly repositories: readonly string[];
    /** The number of elements in the available repositories, in no view. */
    readonly elements: number;
  };
  /** The licence notice of ReqSeq and where its third-party licences are. */
  readonly license: {
    /** The licence notice of ReqSeq, one item per line. */
    readonly notice: readonly string[];
    /** The file of the delivery that lists the third-party components with their licences, relative to its resources folder. Left out in a build from a checkout. */
    readonly thirdParty?: string;
  };
  /** Where the documentation and the releases are. */
  readonly documentation: {
    /** The folder of the delivery with its documentation site (SR-141), relative to its resources folder, with `/` between its names (`cli/docs`); `reqseq serve docs` serves it. Left out in a build from a checkout. */
    readonly bundled?: string;
    /** The address of the online documentation, as text only: ReqSeq never opens it. */
    readonly online: string;
    /** The address of the releases, as text only: ReqSeq never opens it. */
    readonly releases: string;
  };
}

/**
 * Input of `metamodel.get` as `run` gets it: validated, properties with a `default` filled in. The effective metamodel: types with inherited properties and statuses, properties with whether they count to the version, relation kinds, statuses, meanings, the files read.
 * Schema: `schemas/commands/metamodel.get.json input`.
 */
export type MetamodelGetInput = Readonly<Record<string, never>>;

/**
 * Output of `metamodel.get`. The effective metamodel: types with inherited properties and statuses, properties with whether they count to the version, relation kinds, statuses, meanings, the files read.
 * Schema: `schemas/commands/metamodel.get.json output`.
 */
export interface MetamodelGetOutput {
  /** The types with inheritance resolved (SR-012), in metamodel order; `statuses` are the statuses each type offers (ThomasBirkmaier/ReqSeq-archive#306). */
  readonly types: readonly MetamodelEffectiveType[];
  /** The property definitions as written, except that each carries `content`, false when not written: whether a change of its value gives a new version and makes evidence and relations outdated (D-057, #624). */
  readonly properties: readonly (MetamodelProperty & {
    readonly content: unknown;
  })[];
  readonly relations: readonly MetamodelRelationKind[];
  readonly statuses: readonly MetamodelStatus[];
  /** Every built-in meaning of metamodel.schema.json (`meaning` of types, properties and relation kinds) -> the keys whose own definition declares it, in metamodel order; empty if unassigned (SR-013 AK3). In a valid metamodel a type or property meaning has at most one key, a relation meaning any number. Types that inherit a meaning, or repeat the one they inherit, are not listed; `types` shows their effective `meaning`. */
  readonly meanings: Readonly<Record<string, readonly Key[]>>;
  /** The metamodel files that were read, in the order they were merged, faulty ones included: the repository of the metamodel and the path relative to it (#625). Empty when the folder is missing or has no metamodel files. */
  readonly files: readonly WorkspaceLocation[];
  readonly problems?: readonly Problem[];
}

/**
 * Input of `element.create` as `run` gets it: validated, properties with a `default` filled in. Create an element with a new random UUID and the initial status of its type. Only title, text and required properties are needed; empty required properties give a hint (SR-064).
 * Schema: `schemas/commands/element.create.json input`.
 */
export interface ElementCreateInput {
  readonly type: Key;
  /** Title of the new element. */
  readonly title: string;
  /** Markdown text of the element, written below the frontmatter after one blank line; that blank line after the closing `---` is not part of the text. A final line break is added (ADR-0004). Another element is named by a Markdown link, `[Title](reqseq:N-6010df)` with its UUID, short ID or identifier, which is written as UUID and version; `reqseq:N-6010df` alone is no link and counts for nothing. */
  readonly text?: string;
  /** Values of the properties of the type, by key. */
  readonly properties?: Readonly<Record<string, ElementInputValue>>;
  /** Relations of the new element by kind, written in the same file (#175), e.g. {"derives-from": ["N-073", "N-030"], "based-on": "D-062"}; on the CLI --relations derives-from='["N-073","N-030"]' --relations based-on=D-062. */
  readonly relations?: RelationRefs;
  /** Workspace name of the repository to write the element to. Default: the main repository. */
  readonly repository?: string;
  /** Folder relative to the repository; default from the type. */
  readonly folder?: string;
}

/**
 * Output of `element.create`. Create an element with a new random UUID and the initial status of its type. Only title, text and required properties are needed; empty required properties give a hint (SR-064).
 * Schema: `schemas/commands/element.create.json output`.
 */
export interface ElementCreateOutput {
  readonly element: DataExportElement;
  /** The elements the element names by UUID only, each once in the order first named: the variants of `validity` and the views and missing children of `verification`, as element.get names them (#1216). Left out when it names none. */
  readonly names?: readonly ElementName[];
  /** Written files, relative to the workspace root. */
  readonly files: readonly string[];
  readonly problems?: readonly Problem[];
}

/**
 * Input of `element.get` as `run` gets it: validated, properties with a `default` filled in. One element with text, properties, relations, version (and on request its date), hints, and which variants replace or exclude it.
 * Schema: `schemas/commands/element.get.json input`.
 */
export interface ElementGetInput {
  readonly ref: ElementRef;
  readonly view?: View;
  /** Also give the date of the version (`versionDate`, D-013, ADR-0005), read from the Git history. Without it no git runs and `versionDate` is left out, so opening an element stays fast (SR-082 AK3); the app asks for the date in a second call. */
  readonly versionDate: boolean;
  /** Date only the outdated relations and inline references and the changed core requirements of replacements among the hints (`relation.outdated`, `variant.core-changed`: `storedDate`, `currentDate`, `storedCommit`, `currentCommit` and both dates with their commits in the message, D-013, ADR-0005, #252), not the version of the element itself. Git reads only the histories of their targets, and none when the element has no outdated relation; the app asks for it in a second call after the element is shown, only for an element with such hints (SR-110 AK2, SR-082 AK3). `versionDate` dates these hints too. */
  readonly hintDates: boolean;
  /** Which of the elements ref names is meant: the workspace name of its repository, as details.candidates of ref.ambiguous give it (for example one copy of a file whose UUID another file shares, SR-088; ThomasBirkmaier/ReqSeq-archive#255). Only the elements ref names count; when none of them lies there, the error is ref.unknown with them as details.candidates. */
  readonly repository?: string;
  /** Which of the elements ref names is meant: its file, relative to its repository, as details.candidates of ref.ambiguous give it (ThomasBirkmaier/ReqSeq-archive#255). Give repository too when the same path is in several repositories; when several elements are still left, the error is ref.ambiguous with them. */
  readonly file?: RelativePath;
}

/**
 * Output of `element.get`. One element with text, properties, relations, version (and on request its date), hints, and which variants replace or exclude it.
 * Schema: `schemas/commands/element.get.json output`.
 */
export interface ElementGetOutput {
  /** Text, properties, version (in normal form n2, the form the tool writes; a stored version of n1 is compared in its own form, ADR-0005) and, with the input `versionDate`, its date (`versionDate`, D-013, ADR-0005: the committer date in UTC of the newest commit that started this version; null for content no commit has and when Git cannot tell, including a git call that timed out; left out without the input), the own relations, the successors of a superseded element (SR-072 AK3), the hints of the element (none while the metamodel is not valid; also `variant.superseded-in-validity`, SR-040 AK3, `variant.target-not-core` for a replacement or exclusion of the element that names no core requirement, SR-041 AK8, the outdated relations and inline references of the element, `relation.outdated`, and the changed core requirements of its replacements, `variant.core-changed` (SR-045), at a variant the core requirements changed or new since its newest baseline, `variant.core-changed-since-baseline` and `variant.core-new-since-baseline` (SR-103), SR-026 AK3, whose messages name the dates of both versions only with the input `versionDate` or `hintDates`, and `metamodel.meaning-unassigned` when no property has the meaning title) and `readOnly`, always given (unknown type, invalid metamodel or a repository folder that cannot be written). An element with a value that counts and has no normal form (`.inf`, `.nan`, ADR-0005) comes without `version` and `versionDate`, with a `file.faulty` warning last in its hints that says why (ThomasBirkmaier/ReqSeq-archive#276). The incoming relations of every kind: `trace.neighbourhood` with `direction: down`. `verification`, for an element whose type has the meaning `requirement`: its verification status in each view it is in by the view rule (SR-043, SR-047 AK3), as evidence.status gives it (SR-031), with the indirect verification and the children that are missing (SR-034). `validation`: its validation status (SR-038), for every need and for a requirement with a validation record (a validation record of any other element counts for no status, SR-038 AK5), separate from `verification`. `replacedBy` and `excludedBy`, for a core requirement: the variants that replace it (with the replacing requirement) and those that exclude it (SR-046 AK3). */
  readonly element: DataExportElement;
  /** Of the file this answer was read from, for expectedFileSha256 of element.update (SR-106). */
  readonly fileSha256: FileSha256;
  /** The elements the element names by UUID only, each once in the order first named: the variants of `validity`, `replacedBy` and `excludedBy`, the replacements and the views of `verification` (SR-046 AK1/AK2, SR-047 AK3, ThomasBirkmaier/ReqSeq-archive#588). Left out when it names none. */
  readonly names?: readonly ElementName[];
  /** A repository of the workspace is not here (SR-006 AK2): replacements, exclusions and records stored there are missing. */
  readonly incomplete?: Incomplete;
}

/**
 * Input of `element.resolve` as `run` gets it: validated, properties with a `default` filled in. Resolve a reference from another tool (UUID, short ID or identifier, optional version) and tell whether the version is current.
 * Schema: `schemas/commands/element.resolve.json input`.
 */
export interface ElementResolveInput {
  readonly ref: ElementRef;
  /** The version the reference stores (D-013); optional. A version of normal form n1 or n2 is compared with the current version in its own form; a version of another normal form is refused with input.invalid (ADR-0005). */
  readonly version?: Version;
  /** Also give the date of the current version (`versionDate`, D-013, ADR-0005), read from the Git history, as element.get does with the same input. Without it no git runs and `versionDate` is left out. */
  readonly versionDate: boolean;
  /** Which of the elements ref names is meant: the workspace name of its repository, as details.candidates of ref.ambiguous give it (for example one copy of a file whose UUID another file shares, SR-088; ThomasBirkmaier/ReqSeq-archive#255). Only the elements ref names count; when none of them lies there, the error is ref.unknown with them as details.candidates. */
  readonly repository?: string;
  /** Which of the elements ref names is meant: its file, relative to its repository, as details.candidates of ref.ambiguous give it (ThomasBirkmaier/ReqSeq-archive#255). Give repository too when the same path is in several repositories; when several elements are still left, the error is ref.ambiguous with them. */
  readonly file?: RelativePath;
}

/**
 * Output of `element.resolve`. Resolve a reference from another tool (UUID, short ID or identifier, optional version) and tell whether the version is current.
 * Schema: `schemas/commands/element.resolve.json output`.
 */
export interface ElementResolveOutput {
  /** The element as element.get shows it, with title, text, status, current version in normal form n2 (SR-060 AK1, ADR-0005), verification status per view it is in (SR-031, SR-034, SR-047 AK3) and validation status (SR-038) and, with the input `versionDate`, the date of that version (as element.get gives it; left out without the input). Without a version (a value that counts has no normal form) `version` and `versionDate` are left out and the hints end with a `file.faulty` warning, as in element.get (ThomasBirkmaier/ReqSeq-archive#276). An unknown reference is the error ref.unknown, one that fits several elements ref.ambiguous with details.candidates (AK3). A short ID whose prefix fits no element stays ref.unknown, never another element; when its tail fits exactly one element of another type, details.candidates names that element and the message asks whether its short ID was meant (prefix may be outdated, ThomasBirkmaier/ReqSeq-archive#275). */
  readonly element: DataExportElement;
  /** Whether the given version is the element's current version, computed from its file as it is now (SR-060 AK2): "current" or "outdated"; "unknown" when the element has no version to compare with (a value that counts has no normal form, `.inf` or `.nan`, ADR-0005: `element` comes without `version` and with a `file.faulty` warning that says why, ThomasBirkmaier/ReqSeq-archive#276); null when no version was given. Strings, not booleans, so a caller that tests the field for truth never takes "unknown" for current. */
  readonly current: "current" | "outdated" | "unknown" | null;
  /** The elements the element names by UUID only, as element.get gives them: the variants of `validity`, `replacedBy` and `excludedBy`, the replacements and the views of `verification` (SR-046 AK1/AK2, SR-047 AK3, ThomasBirkmaier/ReqSeq-archive#588, #456). Left out when it names none. */
  readonly names?: readonly ElementName[];
  /** A repository of the workspace is not here (SR-006 AK2): replacements, exclusions and records stored there are missing (#456). */
  readonly incomplete?: Incomplete;
}

/**
 * Input of `element.list` as `run` gets it: validated, properties with a `default` filled in. Elements of a selection, sorted; optionally as derivation tree or in groups.
 * Schema: `schemas/commands/element.list.json input`.
 */
export interface ElementListInput {
  /** Every part given must hold (SR-101 AK2). */
  readonly selection?: ElementSelection;
  /** Keys in order: ties go to the next key, then to the workspace order (also without sort). `hierarchy` only first: the list is then the derivation tree, see `tree`. Without sort, the sort of the saved filter in `selection.filter`. */
  readonly sort?: readonly FilterSortKeyWithDefaults[];
  /** Group the list (SR-149): `type` (as written, a subtype is a group of its own), `status`, `package` (the property with the meaning `packages`), or the key of a property whose values element.facets offers: a choice or relation property, or a text, number or date property with few values shared in the workspace (a topic, not a title). Whether a text, number or date key can be grouped follows the data of the workspace (the element.facets rule with its default maxValues of 30), so the same key can become input.invalid as the data changes. Any other key is input.invalid. Groups come in the order a sort by the value gives: types, statuses and choices in metamodel order (a choice written by its display name is in the group of that choice), then other values: numbers, texts ignoring case, booleans; packages and other targets by title ignoring case, then short ID (spec-frage #978). Elements without a value form the last group; so do elements whose targets are all not available (`unavailable`). Relation items are read as element.facets and the condition `property eq` read them. An element with several values (packages, a list) is in each of their groups. `sort` (or the saved filter's sort) orders the elements inside each group; with `hierarchy` each group is its own tree. Nothing is stored. */
  readonly group?: GroupKey;
  /** Give only these fields of each element (#982), in `partial` instead of `elements`; unlike the `fields` of element.search, which says where to search. `id`, `shortId`, `repository` and the `problems` of an element are always given; a field the element has no value for stays left out, as without `fields`. `text` gives the text as `withText` does, also with `withText` false. Without `fields`, every field in `elements`. */
  readonly fields?: readonly (
    | "identifier"
    | "type"
    | "status"
    | "title"
    | "text"
    | "version"
    | "file"
    | "emergent"
    | "properties"
    | "relations")[];
  /** Also give the text of each element. Left out for an element without a version, and when its file changed while the list was built (list again). */
  readonly withText?: boolean;
  /** Also give what each row shows of its element's verification (SR-137), in `rowVerification`. */
  readonly withVerification?: boolean;
  /** The most elements on one page. */
  readonly limit: number;
  /** Elements skipped before the page. */
  readonly offset: number;
}

/**
 * Output of `element.list`. Elements of a selection, sorted; optionally as derivation tree or in groups.
 * Schema: `schemas/commands/element.list.json output`.
 */
export type ElementListOutput = {
  /** Without `fields`: one page of the list. With `group`, the page of the grouped list (the elements of the first group, then of the next): an element in several groups is listed once in each, so a page can hold it more than once; key the rows by their position, not by the element. */
  readonly elements?: readonly DataExportElement[];
  /** Only with `fields`, instead of `elements`: the same page, each element with the fields asked for. */
  readonly partial?: readonly DataExportElementPart[];
  /** Only with `withVerification`: for each row of `elements` (or `partial`), in the same order, the verification status of a requirement and the progress ring of a requirement or need, as a node of trace.graph carries them (SR-137 AK1, AK3). */
  readonly rowVerification?: readonly DataExportRowVerification[];
  /** Only when `sort` starts with `hierarchy` (SR-075 AK2): the place in the derivation tree of each element of `elements` (or `partial`), in the same order. With `group`, each group is its own tree over its elements: a parent outside the group does not count. The list is the tree depth first: each root, then the elements below it. Each element of the selection appears once (spec-frage ThomasBirkmaier/ReqSeq-archive#354): below the parent of the list that reaches it at the shortest depth, the first in sort order among equals; an element without a parent in the list is a root, and so is the first element in sort order of a cycle that no root reaches. Its other parents are in its `relations`. */
  readonly tree?: readonly {
    readonly id: Uuid;
    /** Workspace name of the repository of the element. */
    readonly repository: string;
    /** 0 for a root, 1 for an element below it, and so on. */
    readonly depth: number;
    /** The element it is shown below, a parent of it by a derivation; left out for a root. It may lie on an earlier page. */
    readonly parent?: {
      readonly id: Uuid;
      /** Workspace name of the repository of the parent. */
      readonly repository: string;
    };
  }[];
  /** Only with `group`: every group of the whole list in order, also those on other pages; a group without elements is not given. `offset` and `rows` follow from the counts and are given for convenience. */
  readonly groups?: readonly ListGroup[];
  /** Only with `group`: the row the page starts at (the `offset` of the input), so that a page can be headed by its groups without the input. */
  readonly offset?: number;
  /** Only with `group`: the rows of the grouped list, the sum of the counts of `groups`; `offset` and `limit` page over these rows. At least `total`, more when elements are in several groups. */
  readonly rows?: number;
  /** Elements in the selection, each once. */
  readonly total: number;
  readonly incomplete?: Incomplete;
} & (
  | {
    readonly elements: unknown;
  }
  | {
    readonly partial: unknown;
  });

/**
 * Input of `element.facets` as `run` gets it: validated, properties with a `default` filled in. Types, statuses and property values of the elements of a selection, with counts, to choose a filter from.
 * Schema: `schemas/commands/element.facets.json input`.
 */
export interface ElementFacetsInput {
  /** Every part given must hold (SR-101 AK2). Without it, every element. */
  readonly selection?: ElementSelection;
  /** A property of kind text, number or date gives its values only when it has at most this many distinct values in the whole workspace and at least one of them is shared by two elements; otherwise it is free text, found with element.search (SR-068). Choice and relation properties always give their values. */
  readonly maxValues: number;
}

/**
 * Output of `element.facets`. Types, statuses and property values of the elements of a selection, with counts, to choose a filter from.
 * Schema: `schemas/commands/element.facets.json output`.
 */
export interface ElementFacetsOutput {
  /** Elements in the selection. */
  readonly total: number;
  /** The types of the selected elements as written in the files, with the number of elements of exactly this type (an element of a subtype is not counted under its parent): types of the metamodel in metamodel order with their name, then other type keys in store order (name = key). Types without a selected element are not listed (SR-118). */
  readonly types: readonly {
    /** Key of the type as written in the files. */
    readonly key: string;
    /** Display name of the type; the key for a type the metamodel does not define. */
    readonly name: string;
    /** Selected elements of exactly this type. */
    readonly count: number;
  }[];
  /** The statuses of the selected elements as written in the files, with the number of elements: statuses of the metamodel in metamodel order, then other values in store order. Elements without status are not counted. */
  readonly statuses: readonly {
    /** Key of the status as written in the files. */
    readonly key: string;
    /** Selected elements with this status. */
    readonly count: number;
  }[];
  /** Every property that a type of a selected element has, in the order of the property definitions of the metamodel. Keys no type has (SR-016) are not listed. The counts and values are those of all selected elements, as the filter conditions read them (any type, SR-069): an element whose type lacks the property counts by the value its file holds (usually none). */
  readonly properties: readonly {
    readonly key: Key;
    /** Display name of the property. */
    readonly name: string;
    /** Value kind of the property. */
    readonly kind: "text" | "number" | "date" | "choice" | "relation";
    /** Selected elements that have some value. */
    readonly count: number;
    /** Selected elements that have no value (absent, null or []); the elements `{ property, op: "missing" }` selects. */
    readonly missing: number;
    /** Distinct values the property can be filtered on (for a relation property: distinct available targets). Free text without values counts only up to maxValues + 1, see distinctCapped. */
    readonly distinct: number;
    /** Only for free text: there are more distinct values than maxValues, and `distinct` stopped counting at maxValues + 1. */
    readonly distinctCapped?: true;
    /** Left out for free text (see maxValues). Choices: in metamodel order, then other values as written. Relation targets: by title ignoring case, then short ID. Others: numbers ascending, then texts ignoring case, then booleans. Each value is what a property condition takes with op eq and selects exactly the elements counted: for a relation target its short ID; a choice stored under a name the condition would map to another key, or one that names several choices, is not given. Targets that are not available are left out (a condition cannot name them). */
    readonly values?: readonly {
      /** The value, as `{ property, op: "eq", value }` selects it. */
      readonly value: string | number | boolean;
      /** Selected elements that have this value. */
      readonly count: number;
      /** Display name of a choice. */
      readonly name?: string;
      /** Title of a relation target; left out when it has none. */
      readonly title?: string;
      /** Identifier of a relation target, when it has one. */
      readonly identifier?: string;
    }[];
  }[];
  readonly incomplete: Incomplete;
}

/**
 * Input of `element.update` as `run` gets it: validated, properties with a `default` filled in. Change title, text or properties of one element. Unknown properties are kept, and unset removes one (#189); status changes only via element.setStatus, and the origin of an imported element only via reqif.import (SR-057).
 * Schema: `schemas/commands/element.update.json input`.
 */
export interface ElementUpdateInput {
  readonly ref: ElementRef;
  /** New title. */
  readonly title?: string;
  /** New Markdown text of the element; the blank line after the closing `---` is not part of the text, so the text element.get gives can be passed back unchanged. A changed text gets a final line break (ADR-0004). Another element is named by a Markdown link, `[Title](reqseq:N-6010df)` with its UUID, short ID or identifier, which is written as UUID and version; `reqseq:N-6010df` alone is no link and counts for nothing. */
  readonly text?: string;
  /** New values by key. */
  readonly set?: Readonly<Record<string, ElementInputValue>>;
  /** Keys to remove. */
  readonly unset?: readonly Key[];
  /** List items by position from 1: 1..n replace, n+1.. append; other items keep their bytes. Needs expectedFileSha256. */
  readonly setItems?: Readonly<Record<string, Readonly<Record<string, ElementScalar>>>>;
  /** Relations to add by kind, as relation.add adds them, in the same file write (#175). A relation the element has with a valid version is kept. */
  readonly addRelations?: RelationRefs;
  /** Relations to remove by kind, as relation.remove removes them (a UUID as given), in the same file write (#175). Nothing to remove is an info problem relation.not-found. */
  readonly removeRelations?: RelationRefs;
  /** Which of the elements ref names is meant: the workspace name of its repository, as details.candidates of ref.ambiguous give it. Only the elements ref names count; when none of them lies there, the error is ref.unknown with them as details.candidates. */
  readonly repository?: string;
  /** Write precondition (SR-106): the fileSha256 the change was made on, from element.get. Required with title, text or setItems, else input.invalid (precondition-missing); optional for set, unset and relations alone. If the file has other bytes now, nothing is written: file.changed-on-disk, also when nothing would change. */
  readonly expectedFileSha256?: FileSha256;
}

/**
 * Output of `element.update`. Change title, text or properties of one element. Unknown properties are kept, and unset removes one (#189); status changes only via element.setStatus, and the origin of an imported element only via reqif.import (SR-057).
 * Schema: `schemas/commands/element.update.json output`.
 */
export interface ElementUpdateOutput {
  readonly element: DataExportElement;
  /** The elements the element names by UUID only, each once in the order first named: the variants of `validity` and the views and missing children of `verification`, as element.get names them (#1216). Left out when it names none. */
  readonly names?: readonly ElementName[];
  /** Of the file as written, or as read when nothing changed (SR-106). */
  readonly fileSha256: FileSha256;
  /** Written files, relative to the workspace root. */
  readonly files: readonly string[];
  /** The number of directly affected elements (SR-024 AK2): the distinct elements other than this one whose files hold a relation or an inline reference to it, the elements at distance 1 of `trace.affected`. Counted only when the save changed what the version is computed from in normal form n1 or n2 (the content, D-013, ADR-0005), so also when it changed only the stored version of a reference: a link that stores n1 of this element becomes outdated by it; 0 when only the title or properties that do not count to the version changed, or nothing changed (SR-024 AK3). For an element without a version (a value that counts has no normal form, ADR-0005) what the version is computed from is compared, so a save of only its title or status also gives 0 (ThomasBirkmaier/ReqSeq-archive#276). */
  readonly affected: number;
  readonly problems?: readonly Problem[];
}

/**
 * Input of `element.setStatus` as `run` gets it: validated, properties with a `default` filled in. Set or remove the status of elements on explicit request of the caller. Besides element.supersede the only command that changes a status; no command changes one on its own (D-030, SR-087).
 * Schema: `schemas/commands/element.setStatus.json input`.
 */
export interface ElementSetStatusInput {
  readonly refs: readonly ElementRef[];
  /** Key or display name of a status of the metamodel, in any case; the key is written. It must be a status of the element's type (ThomasBirkmaier/ReqSeq-archive#306). null removes the status line, only from an element whose type has an optional status: no status, or only statuses marked invalid (ThomasBirkmaier/ReqSeq-archive#343); else input.invalid with reason status-required. */
  readonly status: KeyOrName | null;
}

/**
 * Output of `element.setStatus`. Set or remove the status of elements on explicit request of the caller. Besides element.supersede the only command that changes a status; no command changes one on its own (D-030, SR-087).
 * Schema: `schemas/commands/element.setStatus.json output`.
 */
export interface ElementSetStatusOutput {
  readonly files: readonly string[];
  readonly problems?: readonly Problem[];
}

/**
 * Input of `element.supersede` as `run` gets it: validated, properties with a `default` filled in. Supersede an element: set an invalid status of its type and optionally name a successor (relation with meaning succession, written into the successor's file). There is no delete (D-045).
 * Schema: `schemas/commands/element.supersede.json input`.
 */
export interface ElementSupersedeInput {
  readonly ref: ElementRef;
  /** Key or display name of a status of the metamodel, in any case; the key is written. It must be a status of the element's type that the metamodel marks invalid (ThomasBirkmaier/ReqSeq-archive#306). */
  readonly status: KeyOrName;
  readonly successor?: ElementRef;
  /** Relation kind with meaning succession to write from the successor; needed only when more than one fits the types and the successor does not already have the relation under exactly one of them. */
  readonly relation?: Key;
}

/**
 * Output of `element.supersede`. Supersede an element: set an invalid status of its type and optionally name a successor (relation with meaning succession, written into the successor's file). There is no delete (D-045).
 * Schema: `schemas/commands/element.supersede.json output`.
 */
export interface ElementSupersedeOutput {
  readonly files: readonly string[];
  readonly problems?: readonly Problem[];
}

/**
 * Input of `element.bulkUpdate` as `run` gets it: validated, properties with a `default` filled in. Set, add to or remove one property for all elements of a selection; without confirm it only previews what changes. Never id, type or status.
 * Schema: `schemas/commands/element.bulkUpdate.json input`.
 */
export interface ElementBulkUpdateInput {
  readonly selection: ElementSelection;
  /** A property of the metamodel; not the title key, not a relation kind. */
  readonly property: Key;
  /** set: replace the value. add: append the items an element does not hold yet (a property with many). remove: without value the property, with value these items (many). */
  readonly operation: "set" | "add" | "remove";
  /** For set and add. A choice by key or name; relation targets as for element.update. */
  readonly value?: ElementInputValue;
  /** Write the change; without it nothing is written. A written file also gets the current titles of its same-repository relation targets (decision on ThomasBirkmaier/ReqSeq-archive#307), which the preview does not show. */
  readonly confirm: boolean;
  /** The count of the preview: with confirm, refused (nothing written) when the change now affects another number of elements. Prefer plan. */
  readonly expected?: number;
  /** The preview's plan: with confirm, refused (nothing written) unless the same files get the same bytes. */
  readonly plan?: string;
}

/**
 * Output of `element.bulkUpdate`. Set, add to or remove one property for all elements of a selection; without confirm it only previews what changes. Never id, type or status.
 * Schema: `schemas/commands/element.bulkUpdate.json output`.
 */
export interface ElementBulkUpdateOutput {
  /** True when the files were written (confirm). */
  readonly applied: boolean;
  /** Number of affected elements (SR-071 AK2). */
  readonly count: number;
  /** The elements whose file the change rewrites, in store order. */
  readonly affected: readonly {
    readonly id: Uuid;
    readonly shortId: ShortId;
  }[];
  /** Elements of the selection that have the result already. */
  readonly unchanged: number;
  /** Elements left out because the metamodel does not allow the property for them (SR-071 AK3). */
  readonly skipped: readonly {
    readonly id: Uuid;
    readonly shortId: ShortId;
    /** `not-a-property`: the type of the element does not have the property. `unknown-type`: the metamodel has no type of the element, so it is only read. */
    readonly reason: "not-a-property" | "unknown-type";
    /** Why the element was left out, for people. */
    readonly message: string;
  }[];
  /** Written files relative to the workspace root; empty in a preview. */
  readonly files: readonly string[];
  /** Hints at the property in the affected elements after the change: missing required value, value kind (SR-085), more entries than `max-items` (SR-171), target types (SR-086). A preview also names what a confirmation refuses: a not writable folder (file.read-only). */
  readonly problems: readonly Problem[];
  readonly incomplete?: Incomplete;
  /** Fingerprint of the files the change writes and their new bytes; pass it with confirm. */
  readonly plan: string;
}

/**
 * Input of `element.addAttachment` as `run` gets it: validated, properties with a `default` filled in. Copy an image, from a local file or given as bytes, into the folder named like the element file, next to it, and return the Markdown that embeds it relatively; once the text embeds it, the image counts to the version (SR-097, D-057). Never replaces a file.
 * Schema: `schemas/commands/element.addAttachment.json input`.
 */
export interface ElementAddAttachmentInput {
  readonly ref: ElementRef;
  /** The image to copy: a file ending in .avif, .bmp, .gif, .jpeg, .jpg, .png, .svg or .webp (any case). Give it or content, not both. */
  readonly sourcePath?: LocalPath;
  /** The bytes of the image, base64 (RFC 4648, with padding), at most 20 MiB decoded, so a request stays below the 32 MiB limit of the API and MCP: for an image without a file, such as one pasted or dropped in the app (SR-190 AK3). Needs name; give it or sourcePath, not both. */
  readonly content?: string;
  /** The file name of content, for its extension (which must be one of sourcePath's) and the name of the copy, e.g. Screenshot 2026-11-07.png. Only with content. */
  readonly name?: string;
  /** Which of the elements ref names is meant: the workspace name of its repository, as details.candidates of ref.ambiguous give it (for example one copy of a file whose UUID another file shares, SR-088; ThomasBirkmaier/ReqSeq-archive#255). Only the elements ref names count; when none of them lies there, the error is ref.unknown with them as details.candidates. */
  readonly repository?: string;
  /** Which of the elements ref names is meant: its file, relative to its repository, as details.candidates of ref.ambiguous give it (ThomasBirkmaier/ReqSeq-archive#255). Give repository too when the same path is in several repositories; when several elements are still left, the error is ref.ambiguous with them. */
  readonly file?: RelativePath;
}

/**
 * Output of `element.addAttachment`. Copy an image, from a local file or given as bytes, into the folder named like the element file, next to it, and return the Markdown that embeds it relatively; once the text embeds it, the image counts to the version (SR-097, D-057). Never replaces a file.
 * Schema: `schemas/commands/element.addAttachment.json output`.
 */
export interface ElementAddAttachmentOutput {
  /** The image file relative to the workspace root, / as separator, e.g. requirements/SR-825b7146fb54/layout.png. Its name is the source name with only ASCII letters, digits, _ and -, and -2, -3, ... when the folder has that name already; a file there with the same bytes is reused. */
  readonly file: string;
  /** The image as Markdown with a link relative to the element file, e.g. ![layout](SR-825b7146fb54/layout.png), to insert into the text and save with element.update. */
  readonly markdown: string;
}

/**
 * Input of `relation.options` as `run` gets it: validated, properties with a `default` filled in. Relation kinds the metamodel allows from an element, each with the types its target may have (SR-067); search a target with element.search and selection.where: { type: targetTypes }.
 * Schema: `schemas/commands/relation.options.json input`.
 */
export interface RelationOptionsInput {
  /** The element that gets the relation (its source). */
  readonly ref: ElementRef;
  /** Only this relation kind: none when the type of the element does not allow it. */
  readonly kind?: Key;
}

/**
 * Output of `relation.options`. Relation kinds the metamodel allows from an element, each with the types its target may have (SR-067); search a target with element.search and selection.where: { type: targetTypes }.
 * Schema: `schemas/commands/relation.options.json output`.
 */
export interface RelationOptionsOutput {
  /** In metamodel order: every relation kind whose source-types allow the type of the element (subtypes count) and whose target-types allow some type; none for an element of a type the metamodel does not know (SR-016 AK3). These are the kinds relation.add accepts. */
  readonly kinds: readonly {
    readonly kind: Key;
    /** Display name of the relation kind. */
    readonly name: string;
    /** Every type of the metamodel a target may have, subtypes included, in metamodel order; relation.add refuses a target of another known type. */
    readonly targetTypes: readonly Key[];
  }[];
}

/**
 * Input of `relation.add` as `run` gets it: validated, properties with a `default` filled in. Add a relation; stores target UUID and current version, plus the title only within the same repository. A relation over a limit of the kind is saved too, with a relation.too-many hint.
 * Schema: `schemas/commands/relation.add.json input`.
 */
export interface RelationAddInput {
  readonly source: ElementRef;
  readonly kind: Key;
  readonly target: ElementRef;
}

/**
 * Output of `relation.add`. Add a relation; stores target UUID and current version, plus the title only within the same repository. A relation over a limit of the kind is saved too, with a relation.too-many hint.
 * Schema: `schemas/commands/relation.add.json output`.
 */
export interface RelationAddOutput {
  /** Written files, relative to the workspace root. */
  readonly files: readonly string[];
  readonly problems?: readonly Problem[];
}

/**
 * Input of `relation.remove` as `run` gets it: validated, properties with a `default` filled in. Remove a relation from the source file.
 * Schema: `schemas/commands/relation.remove.json input`.
 */
export interface RelationRemoveInput {
  readonly source: ElementRef;
  readonly kind: Key;
  readonly target: ElementRef;
  /** Only relations into this repository (workspace name); a relation that names none points into the source's repository (D-058). Names the one meant when a UUID has relations into several repositories. */
  readonly repository?: string;
}

/**
 * Output of `relation.remove`. Remove a relation from the source file.
 * Schema: `schemas/commands/relation.remove.json output`.
 */
export interface RelationRemoveOutput {
  readonly files: readonly string[];
  readonly problems?: readonly Problem[];
}

/**
 * Input of `trace.chain` as `run` gets it: validated, properties with a `default` filled in. Chain up to the top parents and down to evidence, with depth, gaps (also a requirement without a parent) and cycles; one page of nodes at a time, total counts all; the validation records of the root.
 * Schema: `schemas/commands/trace.chain.json input`.
 */
export interface TraceChainInput {
  readonly ref: ElementRef;
  /** `up` to the parents, `down` to the children and evidence, `both` for both. */
  readonly direction: "up" | "down" | "both";
  readonly view?: View;
  /** The deepest level in each direction; without it the chain is followed to its ends. */
  readonly maxDepth?: number;
  /** Nodes of the page; total counts all. The walk is always complete: depth, gaps, cycles and incomplete are those of the whole chain (spec-frage ThomasBirkmaier/ReqSeq-archive#290). Every page walks the whole chain again; to step through a chain, ask with `maxDepth` instead. */
  readonly limit: number;
  /** Nodes skipped before the page, in the order of `nodes` (the root, then the parents level by level, then the children level by level). */
  readonly offset: number;
  /** Which of the elements ref names is meant: the workspace name of its repository, as details.candidates of ref.ambiguous give it (for example one copy of a file whose UUID another file shares, SR-088; ThomasBirkmaier/ReqSeq-archive#255). Only the elements ref names count; when none of them lies there, the error is ref.unknown with them as details.candidates. */
  readonly repository?: string;
  /** Which of the elements ref names is meant: its file, relative to its repository, as details.candidates of ref.ambiguous give it (ThomasBirkmaier/ReqSeq-archive#255). Give repository too when the same path is in several repositories; when several elements are still left, the error is ref.ambiguous with them. */
  readonly file?: RelativePath;
}

/**
 * Output of `trace.chain`. Chain up to the top parents and down to evidence, with depth, gaps (also a requirement without a parent) and cycles; one page of nodes at a time, total counts all; the validation records of the root.
 * Schema: `schemas/commands/trace.chain.json output`.
 */
export interface TraceChainOutput {
  readonly root: Uuid;
  /** Every element of the chain once per direction, at its shortest depth (SR-022 AK1, AK2): the root first, then the parents level by level, then the children level by level. An element reached again (a diamond, a cycle) is not repeated; its edge is in `edges` (SR-022 AK4). In a view, only the elements the view holds (SR-040, SR-043: not a core requirement the variant excludes or replaces, nor what hangs only below it); the root always. An element is named by its UUID and `repository` (D-058); two files of one repository with the same UUID (SR-088) are two nodes, told apart only by `file`, and edges and gaps name both the same way. Only the page of `limit` nodes from `offset` (in this order) is listed; `total` counts every node. A chain can be large (in a workspace of 50,000 elements and 200,000 relations up to about 42,000 nodes): a client asks for the first page and further ones as needed (SR-082 AK4, spec-frage ThomasBirkmaier/ReqSeq-archive#290), or shows it step by step with `maxDepth` 1 and asks again below an element that is not `expanded`. */
  readonly nodes: readonly {
    readonly id: Uuid;
    readonly shortId: ShortId;
    /** Its identifier (the value of its property with the meaning `identifier`, such as SR-036, ThomasBirkmaier/ReqSeq-archive#305), for display next to `shortId`; left out when it has none. */
    readonly identifier?: string;
    /** Key of its type. */
    readonly type: string;
    /** Its title; empty without one. */
    readonly title: string;
    /** Its status key as written; left out when it has none. */
    readonly status?: string;
    /** Workspace name of the repository of its file. */
    readonly repository: string;
    /** Path relative to the repository. */
    readonly file: string;
    /** Steps from the root: 0 for the root, 1 for its parents or children, and so on. */
    readonly depth: number;
    /** `up` for a parent (and its parents), `down` for a child (and its children); left out for the root. */
    readonly direction?: "up" | "down";
    /** Its parents or children were looked at; false only at `maxDepth`, where the chain was cut. */
    readonly expanded: boolean;
  }[];
  /** The number of all nodes of the chain; `nodes` holds the page of `limit` from `offset`. */
  readonly total: number;
  /** Every derivation relation the chain followed, from the child that stores it (`source`) to its parent (`target`, ADR-0004): the upward ones, then the downward ones, in the order they were followed. Paged with the nodes: an edge is listed on the page of the node it leads to in its walk (upwards the parent, downwards the child), so every edge is on exactly one page. */
  readonly edges: readonly {
    readonly source: Uuid;
    /** Workspace name of the repository of `source`. */
    readonly sourceRepository: string;
    readonly target: Uuid;
    /** Workspace name of the repository of `target`. */
    readonly targetRepository: string;
    /** Key of the relation kind with the meaning `derivation` (SR-013). */
    readonly kind: Key;
    /** The walk it belongs to: `up` to the parents, `down` to the children. */
    readonly direction: "up" | "down";
    /** Both ends lie in one cycle of derivations (SR-022 AK4). */
    readonly cyclic: boolean;
  }[];
  /** The gaps of the chain, in the order of `nodes` (the `no-parent` gaps of the upward chain first, the root's among them, then those of the downward chain), only those of the nodes of the page. Downward (SR-022 AK3), only for elements whose children were looked at (`expanded`): `no-child` for a need without a child, `no-evidence` for a requirement without a child and without evidence. Upward (SR-022 AK5), only for elements whose parents were looked at, so not with `direction: down`: `no-parent` for a requirement that names no parent through a relation kind with the meaning `derivation`, whatever the view and the state of the target (a parent in a repository that is not here is one); the metamodel says which kinds derive, so in the standard model a requirement based only on a decision (`based-on`) has the gap. `workspace.check` reports the same elements (`trace.no-parent`). `no-evidence`: the element has no verification record in `view`, in the core without `view` (as `evidence.coverage` and the filter condition `verification`; any version and result, spec question ThomasBirkmaier/ReqSeq-archive#527 Q3). A test case that was only skipped does not close the gap. `not-in-view` (#674, product owner decision, 2026-11-02): a requirement without a child that `view` does not hold, without `view` the core (its validity names only variants), instead of `no-evidence`, whatever its records; `views` names the views that hold it. It is no evidence gap: a client that counts the gaps of a chain leaves it out. With `view` only the root can have it, as the chain reaches only elements the view holds. */
  readonly gaps: readonly {
    readonly id: Uuid;
    /** Workspace name of the repository of the element with the gap. */
    readonly repository: string;
    /** The kind of the gap, as `gaps` describes it. */
    readonly kind: "no-child" | "no-evidence" | "no-parent" | "not-in-view";
    /** Only with `not-in-view`: the views that hold the element, `core` first, then the variants in store order; empty when none does (a validity that names no variant of the workspace). `names` names the variants. */
    readonly views?: readonly ViewId[];
  }[];
  /** The evidence of the downward chain (SR-022 AK1, SR-033 AK1 to AK3), in the order of `nodes`, only for the nodes of the page whose children were looked at (`expanded`), paged like `gaps`; one item per element that has any, none with `direction` `up`. Only verification records (D-007); the validation records of the root are in `validationRecords`. With `view` only the records that hold in it (SR-047: the core the records without a variant, a variant those for it and, for an element of a repository marked `variant-independent`, those without a variant, SR-173); without `view` every record, each with its `variant`, as `evidence.list`. A test case all of whose executions of the element hold in another view is left out; a test case that was only skipped shows in every view. The evidence of a record is its `evidence`; a JUnit execution has none, its evidence is its record file (`repository`, `file`, `line`; D-007: for automatic tests the record is the result file). Evidence is text and never opened. */
  readonly evidence: readonly {
    /** The element of the chain the evidence belongs to. */
    readonly id: Uuid;
    /** Workspace name of the repository of that element. */
    readonly repository: string;
    /** The element's depth plus one: the evidence is one level below it (SR-022 AK1). */
    readonly depth: number;
    /** The test cases that name the element (SR-033), by class name, then name, each with the element's own executions newest first (`elements` names every element the test case names, SR-033 AK2); `executed` false for a test case that was only skipped (SR-033 AK3). */
    readonly testCases: readonly DataExportTestCase[];
    /** Unlike `evidence.list` `records`: only the element's records without a test case (inspection, analysis, demonstration, manual records without `test-case`), newest first. */
    readonly records: readonly DataExportEvidenceRecord[];
  }[];
  /** The validation records of the root (SR-038 AK1: the validation shown apart from the verification), newest first, those with a test case too, in either direction; on the page with the root only (`offset` 0), `[]` on the others. `view` does not narrow them: a validation record names no variant (SR-038 AK4) and holds for its element, as its validation status counts it (#646). */
  readonly validationRecords: readonly DataExportEvidenceRecord[];
  /** Derivation relations the chain could not follow (SR-006 AK1, SR-088, SR-089): upwards a parent that is not available, downwards a child whose relation points at a UUID several files of the repository share. The other end is shown by its short ID only when it is not available (prefix `UNKNOWN` when its repository is not on this machine). A parent whose `id` is no UUID is not listed (the value-kind check reports it, SR-085); in a repository that is not here it still makes the chain `incomplete`. Only those of the nodes of the page (`from`). */
  readonly unresolved: readonly {
    /** `up` for a parent that could not be followed, `down` for a child. */
    readonly direction: "up" | "down";
    /** The element of the chain whose parents or children were looked at. */
    readonly from: Uuid;
    /** Workspace name of the repository of `from`. */
    readonly fromRepository: string;
    readonly kind: Key;
    /** The other end: the parent the relation names (up), the child that stores it (down). */
    readonly id: Uuid;
    readonly shortId?: ShortId;
    /** Identifier of the other end (ThomasBirkmaier/ReqSeq-archive#305), when it is available and has one. */
    readonly identifier?: string;
    /** Title of the other end, when it is available. */
    readonly title?: string;
    /** As in `data-export.schema.json#/$defs/relation`; downwards always `ambiguous` (the element the child points at). */
    readonly targetState: "inaccessible" | "missing" | "ambiguous" | "unknown-repository";
  }[];
  /** True when a part of the chain lies in a repository that is not on this machine (SR-006 AK2), in the view of a variant while a repository of the workspace is not on this machine (it may hold a replacement or an exclusion), or an evidence location does: evidence and validation records there are not seen. */
  readonly incomplete: Incomplete;
  /** The variants that the records of `evidence` name by UUID only (`variant`), then those the `views` of `gaps` name, each once in the order first named, so a reader names them by short ID, identifier and title (ThomasBirkmaier/ReqSeq-archive#588, #676). Left out when it names none, and for a variant in a repository that is not here. */
  readonly names?: readonly ElementName[];
  /** Hints: `trace.cycle` once per cycle of derivations in the chain, naming its elements (SR-022 AK4); `metamodel.meaning-unassigned` when no type has the meaning `need` or `requirement`, so those gaps cannot be found (SR-013 AK3; upward only `requirement`). The hints are those of the whole chain, on every page. */
  readonly problems: readonly Problem[];
}

/**
 * Input of `trace.related` as `run` gets it: validated, properties with a `default` filled in. All children of a set of parents, or all parents of a set of requirements, each once, optionally up to a depth; one page at a time, total counts all.
 * Schema: `schemas/commands/trace.related.json input`.
 */
export interface TraceRelatedInput {
  /** The elements to start from: the parents for `children`, the requirements for `parents`. */
  readonly refs: readonly ElementRef[];
  /** `children`: every element derived from them. `parents`: every element they derive from. */
  readonly direction: "children" | "parents";
  /** The most derivation steps from the start elements; without it every step. */
  readonly maxDepth?: number;
  readonly view?: View;
  /** Elements of the page; total counts all. */
  readonly limit: number;
  /** Elements skipped before the page, in the order of the list (by distance from the selection). */
  readonly offset: number;
}

/**
 * Output of `trace.related`. All children of a set of parents, or all parents of a set of requirements, each once, optionally up to a depth; one page at a time, total counts all.
 * Schema: `schemas/commands/trace.related.json output`.
 */
export interface TraceRelatedOutput {
  readonly elements: readonly DataExportElement[];
  /** The number of all related elements; `elements` holds the page. */
  readonly total: number;
  readonly incomplete?: Incomplete;
}

/**
 * Input of `trace.affected` as `run` gets it: validated, properties with a `default` filled in. Elements affected by a change of one element, with path and distance.
 * Schema: `schemas/commands/trace.affected.json input`.
 */
export interface TraceAffectedInput {
  readonly ref: ElementRef;
  /** The most elements on one page. */
  readonly limit: number;
  /** Elements skipped before the page. */
  readonly offset: number;
  /** Which of the elements ref names is meant: the workspace name of its repository, as details.candidates of ref.ambiguous give it (for example one copy of a file whose UUID another file shares, SR-088; ThomasBirkmaier/ReqSeq-archive#255). Only the elements ref names count; when none of them lies there, the error is ref.unknown with them as details.candidates. */
  readonly repository?: string;
  /** Which of the elements ref names is meant: its file, relative to its repository, as details.candidates of ref.ambiguous give it (ThomasBirkmaier/ReqSeq-archive#255). Give repository too when the same path is in several repositories; when several elements are still left, the error is ref.ambiguous with them. */
  readonly file?: RelativePath;
}

/**
 * Output of `trace.affected`. Elements affected by a change of one element, with path and distance.
 * Schema: `schemas/commands/trace.affected.json output`.
 */
export interface TraceAffectedOutput {
  /** The page of `limit` affected elements from `offset` (`total` counts all). The affected elements: every element that has a relation or an inline reference (in the text or in a property marked `markdown`, SR-127) to the element, directly or through the chain (SR-024 AK1), each once at its shortest distance, breadth first, the element itself never. Distance 1: every element whose file holds a relation (any relation kind or relation-valued property) or an inline reference to it. From there onward along the derivation chain (meaning `derivation`, SR-013) and inline references that point at an affected element. */
  readonly affected: readonly {
    readonly id: Uuid;
    readonly shortId: ShortId;
    /** Its identifier (the value of its property with the meaning `identifier`, such as SR-036, ThomasBirkmaier/ReqSeq-archive#305), for display next to `shortId`; left out when it has none. */
    readonly identifier?: string;
    /** Key of its type. */
    readonly type: string;
    /** Its title; empty without one. */
    readonly title: string;
    /** Workspace name of the repository of its file. */
    readonly repository: string;
    /** Path relative to the repository. */
    readonly file: string;
    /** Steps from the element: 1 when this element's file points at it directly. */
    readonly distance: number;
    /** The way: the element asked for first, this element last, each element in between that points at the one before it; each named by UUID and repository (D-058). */
    readonly path: readonly {
      readonly id: Uuid;
      /** Workspace name of the repository of this element of the path. */
      readonly repository: string;
    }[];
    /** How this element points at the one before it on the path: a relation stored under `key` (a relation kind or a relation-valued property), or an inline reference in its text or in a property marked `markdown`. */
    readonly via: {
      /** `relation`: a relation or relation property stored under `key`. `reference`: an inline reference. */
      readonly kind: "relation" | "reference";
      readonly key?: Key;
    };
  }[];
  /** The number of all affected elements; `affected` holds the page of `limit` from `offset`. */
  readonly total: number;
  /** The evidence records of an older version of the element (SR-024 AK4): its records in the evidence folders (SR-028, SR-093) whose `version` is not its current one, newest first. Empty when its current version cannot be computed (its file no longer holds it, an embedded image cannot be read). */
  readonly records: readonly DataExportEvidenceRecord[];
  /** True while a repository of the workspace file is not on this machine: elements there may point at the element (SR-006 AK2). */
  readonly incomplete: Incomplete;
}

/**
 * Input of `trace.neighbourhood` as `run` gets it: validated, properties with a `default` filled in. The surroundings of one element over every relation kind and inline reference, up and down to a depth; each edge says whether it repeats an element and whether it is outdated. One page of nodes at a time.
 * Schema: `schemas/commands/trace.neighbourhood.json input`.
 */
export interface TraceNeighbourhoodInput {
  readonly ref: ElementRef;
  /** The workspace name of the repository of the element ref names, as in element.get (ThomasBirkmaier/ReqSeq-archive#255). */
  readonly repository?: string;
  /** `up`: along the links the element's file stores (its parents, the targets of its other relations and relation properties, its inline references). `down`: along the links that point at it (its children and every element whose file has a relation or an inline reference to it). The source of a link is placed below its target (ADR-0004). */
  readonly direction: "up" | "down" | "both";
  /** The deepest depth in each direction; 0: the root only. Omitted: 1 (the direct neighbours), unless `allLevels` is true. */
  readonly maxDepth?: number;
  /** Walk as far as the links go (the whole chain); not together with `maxDepth`. For the chain alone ask with `meanings: ["derivation"]`. */
  readonly allLevels: boolean;
  /** Keys of relation kinds or of properties of kind `relation` (such as `packages`) to follow. An unknown key is `input.invalid`. See `meanings` for the filter rule. */
  readonly kinds?: readonly Key[];
  /** Relation kinds with these meanings are followed; `reference` stands for inline references. Without `kinds` and `meanings` every relation and reference is followed. Otherwise a link is followed when its key is in `kinds` or its meaning is in `meanings`; an empty list follows nothing. */
  readonly meanings?: readonly ("derivation" | "replacement" | "succession" | "exclusion" | "reference")[];
  readonly view?: View;
  /** Nodes of the page; total counts all. */
  readonly limit: number;
  /** Nodes skipped before the page, in the order of `nodes` (the root, the up walk level by level, the down walk level by level). */
  readonly offset: number;
}

/**
 * Output of `trace.neighbourhood`. The surroundings of one element over every relation kind and inline reference, up and down to a depth; each edge says whether it repeats an element and whether it is outdated. One page of nodes at a time.
 * Schema: `schemas/commands/trace.neighbourhood.json output`.
 */
export interface TraceNeighbourhoodOutput {
  readonly root: Uuid;
  /** Every element reached once per walk, at its shortest depth: the root, then the up walk, then the down walk, each level by level. In a view only the elements the view holds (SR-040, SR-043: not a core requirement the variant excludes or replaces); the root always. Only the page of `limit` nodes from `offset` is listed; `total` counts all. */
  readonly nodes: readonly {
    readonly id: Uuid;
    readonly shortId: ShortId;
    /** Its identifier (the value of its property with the meaning `identifier`, such as SR-036, ThomasBirkmaier/ReqSeq-archive#305), for display next to `shortId`; left out when it has none. */
    readonly identifier?: string;
    /** Key of its type. */
    readonly type: string;
    /** Its title; empty without one. */
    readonly title: string;
    /** Its status key as written; left out when it has none. */
    readonly status?: string;
    /** Workspace name of the repository of its file. */
    readonly repository: string;
    /** Path relative to the repository. */
    readonly file: string;
    /** Steps from the root in its walk: 0 for the root. */
    readonly depth: number;
    /** `up` for an element reached along the links its file stores, `down` for one reached along the links that point at it; left out for the root. */
    readonly direction?: "up" | "down";
    /** Its links were looked at; false only at `maxDepth`, where the walk was cut. */
    readonly expanded: boolean;
  }[];
  /** The number of all nodes; `nodes` holds the page. */
  readonly total: number;
  /** Every link the walks followed, up edges first, then down edges, in walk order; an edge is on the page of the node it leads to in its walk. A hub (a package with many members) can put many edges on one page: leave out `packages` with `kinds` or `meanings`. Not listed: unresolved links (`element.get` and `workspace.check` report them). */
  readonly edges: readonly {
    /** The element whose file stores the link. */
    readonly source: Uuid;
    /** Workspace name of the repository of `source`. */
    readonly sourceRepository: string;
    /** The element the link points at (ADR-0004), whatever the walk direction. */
    readonly target: Uuid;
    /** Workspace name of the repository of `target`. */
    readonly targetRepository: string;
    /** A relation in the frontmatter or an inline reference in the text or in a property marked `markdown`. */
    readonly link: "relation" | "reference";
    /** The frontmatter key, only for `link: relation`. */
    readonly kind?: Key;
    /** The key is a property of kind `relation` (such as `packages`), not a relation kind. */
    readonly property?: true;
    /** The meaning of the relation kind, `reference` for an inline reference; left out for a kind without a meaning and for a property. */
    readonly meaning?: "derivation" | "replacement" | "succession" | "exclusion" | "reference";
    /** The walk it belongs to. */
    readonly direction: "up" | "down";
    /** Both ends lie in one cycle of the walk. */
    readonly cyclic: boolean;
    /** The edge leads, in its walk, to an element that this walk first reached through another edge, or to the root: a repetition (SR-107 AK3). It holds within one call (asking again from a child loses it; to open a tree level by level ask from the same root with a larger `maxDepth`) and within the followed kinds (the tree of derivations comes from `meanings: ["derivation"]`). First means first reached breadth first (spec question ThomasBirkmaier/ReqSeq-archive#421). */
    readonly repeated: boolean;
    /** The link stores a version of normal form 1 or 2, its target is available and has a current version, and the two differ, compared in the stored version's form (SR-025, ADR-0005). */
    readonly outdated: boolean;
  }[];
  readonly incomplete: Incomplete;
}

/**
 * Input of `trace.matrix` as `run` gets it: validated, properties with a `default` filled in. Traceability matrix of a selection: one row per element, one column per relation kind and direction, each cell the elements at the other end, with outdated and missing marks and per column how many rows have a link.
 * Schema: `schemas/commands/trace.matrix.json input`.
 */
export interface TraceMatrixInput {
  /** The rows: every element the selection selects, as `element.list` selects them (every part given must hold, SR-101 AK2). In a variant view (`selection.view`, or the view of the saved filter) a link whose other end the view does not hold (SR-040, SR-043: also a core requirement the variant excludes or replaces) is left out of the cells and the counts, as `trace.neighbourhood` leaves it out of its walk. */
  readonly selection?: ElementSelection;
  /** As in `element.list`: the rows are in the order `element.list` gives for the same `selection` and `sort` (SR-125 AK1). Without `sort`, the sort of the saved filter in `selection.filter`. `hierarchy` first makes the rows the derivation tree and gives each row its `depth`. */
  readonly sort?: readonly FilterSortKeyWithDefaults[];
  /** Keys of the relation kinds or of properties of kind `relation` (such as `packages`) to make columns of. An unknown key is `input.invalid`. Without `kinds`, the columns are the relation kinds of the metamodel (Beziehungsarten, D-043, D-037): relation properties such as the package and the validity are their own built-in meanings (D-012) and form a column only when named here; inline references are no relation kind and never form a column. */
  readonly kinds?: readonly Key[];
  /** Rows of the page; `total` counts all. */
  readonly limit: number;
  /** Rows skipped before the page, in the order of the list. */
  readonly offset: number;
}

/**
 * Output of `trace.matrix`. Traceability matrix of a selection: one row per element, one column per relation kind and direction, each cell the elements at the other end, with outdated and missing marks and per column how many rows have a link.
 * Schema: `schemas/commands/trace.matrix.json output`.
 */
export interface TraceMatrixOutput {
  /** One column per relation kind and direction that occurs in the whole selection (SR-125 AK2), not only on the page: a kind or direction no row has makes no column, except the `out` column of a relation kind whose limits set a minimum (`min` of 1 or more) for the type of a row, which is there even when no row has such a relation (SR-153, spec question #838 Q1). Order: relation kinds in the order of the metamodel, then properties of kind `relation` in property order; per key `out` before `in`. `type` says what a column holds and so the shape of its cells; every column is `relation`. The evidence columns (SR-126) are no column type: their header is `evidence` and their cells are `rows[].testCases` and `rows[].verification`, so a reader of `columns` and `cells` needs no other shape. */
  readonly columns: readonly {
    /** The column holds relations: its cell in each row is an array of relations (`data-export#/$defs/relation`) of `kind` and `direction`. The evidence columns are `evidence`, `rows[].testCases` and `rows[].verification`, not a column type. */
    readonly type: "relation";
    /** Key of the relation kind, or of the property of kind `relation`. */
    readonly kind: Key;
    /** `kind` is the key of a property of kind `relation`, not of a relation kind. */
    readonly property?: true;
    /** The meaning of the relation kind; left out for a kind without a meaning and for a property. */
    readonly meaning?: "derivation" | "replacement" | "succession" | "exclusion";
    /** `out`: the relations the row element's file stores. `in`: the relations of other elements that point at it. */
    readonly direction: "out" | "in";
    /** For `out`, the `name` of the kind (e.g. Derives from); for `in`, its `inverse-name` (e.g. Derived by), the `name` when it has none. A name can be the same for both directions (Distinct from): `direction` tells them apart. */
    readonly name: string;
    /** How many rows of the whole selection have at least one relation in this column (SR-125 AK3, SR-153 AK2), whatever state its other end is in; a relation to a missing target counts. With a view, the relations the cells show. 0 only for a column with minima that no row has a relation in. */
    readonly count: number;
    /** SR-153 AK1: only on the `out` column of a relation kind whose limits set a minimum (`min` of 1 or more) for the type of a row of the whole selection: how many rows have such a minimum (spec question #838 Q2). Rows of an unknown type or with a status the metamodel marks invalid have none (as SR-152). Left out on every other column, which has no gap and no share (SR-153 AK2). */
    readonly expected?: number;
    /** SR-153 AK1: with `expected`, how many of those rows meet all minima of the kind, counted as `hint.list` counts for `relation.too-few` (SR-152): a relation counts when its target is one element of a known type within the minimum's target type; with a view, only a target that applies in it. A row whose count an unreachable target leaves open is not met and no gap (spec question #838 Q5). */
    readonly met?: number;
    /** SR-153 AK1: with `expected`, `met` divided by `expected`. Left out on a column without a minimum (SR-153 AK2). */
    readonly share?: number;
  }[];
  /** The page: one row per element of the list, in its order (SR-125 AK1). */
  readonly rows: readonly {
    readonly id: Uuid;
    /** Workspace name of the repository of the element. */
    readonly repository: string;
    readonly shortId: ShortId;
    /** Its identifier (the value of its property with the meaning `identifier`, such as SR-036), for display next to `shortId`; left out when it has none. */
    readonly identifier?: string;
    /** Key of its type. */
    readonly type: string;
    /** Its status key as written; left out when it has none. */
    readonly status?: string;
    /** Its title; empty without one. */
    readonly title: string;
    /** Path relative to the repository. */
    readonly file: string;
    /** Only when `sort` starts with `hierarchy`: the depth of the element in the derivation tree, as `element.list` gives it in `tree`. */
    readonly depth?: number;
    /** SR-126 AK1, AK2: only with `evidence`, on a row whose type has the meaning `requirement` and that applies in its view. The test cases that name the requirement, with their verification executions that hold in the view of `evidence` (`trace.chain` shows the same test cases in the same view), by class name then name; an empty array when it has none: a gap (AK2). Records without a test case (inspection, analysis, a manual record without `test-case`) are not here; they count for `verification` only (spec question ThomasBirkmaier/ReqSeq-archive#528 Q3). The chain and `evidence.list` give every execution. */
    readonly testCases?: readonly {
      /** The JUnit `name`, or the `test-case` of the Markdown records. */
      readonly name: string;
      /** The JUnit `classname`; left out for a test case of Markdown records. */
      readonly className?: string;
      /** The test case has at least one execution of this requirement in the view (SR-033 AK3). */
      readonly executed: boolean;
      /** The last execution: the newest execution of this requirement in the view, of any version, and of several equally new ones a failed one (SR-126 AK1), with result, date, item and version; its record file (`repository`, `file`, `line`) is the evidence of a JUnit execution. Left out when `executed` is false. */
      readonly last?: DataExportEvidenceRecord;
      /** How the cell is marked (SR-126 AK2; spec questions ThomasBirkmaier/ReqSeq-archive#528 Q1, Q2 and ThomasBirkmaier/ReqSeq-archive#593 Q2), the first that holds: `not-executed` when `executed` is false; `outdated` when no execution in the view is of the requirement's current version, or its current version is not known; `failed` when the newest execution of the current version failed, of several equally new ones when one of them failed, as the verification status counts them (SR-031). Left out otherwise, also when a newer execution of an older version is `last` (#201). */
      readonly mark?: "not-executed" | "outdated" | "failed";
    }[];
    /** SR-126 AK1, AK3: only with `evidence`, on a row whose type has the meaning `requirement` and that applies in its view. Its verification status in the view of `evidence`, one entry, the same as `element.get` and `evidence.status` give for that view: `indirect` when it is verified through its children (AK3). */
    readonly verification?: readonly DataExportVerificationEntry[];
    /** One cell per entry of `columns`, in the same order; a cell takes its shape from the type of its column. For `relation`, an array of the relations of the row element in the column's `kind` and `direction`, each with `shortId` and `title` of the other end when it is available (SR-125 AK2), and an empty array when it has none. An empty cell is no gap by itself: `gaps` names the gaps (SR-153). Outgoing relations come in the order of the file, incoming ones in the order of the incoming index (store order). A relation to an older version of its target is `outdated`, one to a target that is not there has `targetState: "missing"` (SR-125 AK4); for an incoming relation, `outdated` means its source stores an older version of the row element and `currentVersion` is the row element's. */
    readonly cells: readonly (readonly DataExportRelation[])[];
    /** SR-153 AK1: the minima of the row that its cells undershoot, one entry per minimum, in column order and then metamodel order; a cell is a gap when an entry names its column. Only `out` columns of relation kinds whose limits set a minimum for the row's type; a cell can hold relations and be a gap (to a missing target, or to an element of another type). Counted as `expected` and `met` count. Left out when the row has none. */
    readonly gaps?: readonly {
      /** The index of the column in `columns`, and so of the cell in `cells`. */
      readonly column: number;
      /** The target type of the minimum. */
      readonly targetType: Key;
      /** The display name of `targetType`. */
      readonly targetName: string;
      /** The relations that count for the minimum, as `relation.too-few` gives `count`. */
      readonly count: number;
      /** The minimum, the `min` of the limit (the `limit` of `relation.too-few`; not the page size `limit` of the input). */
      readonly min: number;
    }[];
  }[];
  /** The number of rows of the whole selection. */
  readonly total: number;
  /** The selection is incomplete (SR-006 AK2), or the workspace file lists a repository that is not on this machine: relations of elements there that point at a row cannot be seen, and its elements may belong to the selection. With `evidence`, also when an evidence location lies in such a repository: its records are not seen (SR-006 AK2). */
  readonly incomplete: Incomplete;
  /** The header of the evidence columns (SR-126): given when the workspace file names an evidence location, the metamodel is valid and the selection holds an element whose type has the meaning `requirement` (spec question ThomasBirkmaier/ReqSeq-archive#593 Q1); then every requirement row of the page that applies in `view` has `testCases` and `verification`. Other rows have neither (a requirement valid only in variants, without a view): not applicable, no gap. Left out otherwise, and the output is the one without evidence (SR-125). */
  readonly evidence?: {
    /** The one view of the test cases, the status and the degree: the selection's view, else its saved filter's, else the core (as `evidence.degree`; spec questions ThomasBirkmaier/ReqSeq-archive#593, ThomasBirkmaier/ReqSeq-archive#592 Q1). `element.get` and `evidence.status` give every view. */
    readonly view: ViewId;
    /** SR-126 AK4: the verification degree of the whole selection in `view`, with the count per status, not of the page only; the same as `evidence.degree` gives for the same selection (SR-037). */
    readonly degree: DataExportVerificationDegree;
  };
  /** The elements that `evidence` and the rows' `verification` name by UUID only, each once in the order first named: the variant of the view and the missing children (`missingChildren`), so a reader names them by short ID, identifier and title (ThomasBirkmaier/ReqSeq-archive#588). Left out when they name none. */
  readonly names?: readonly ElementName[];
}

/**
 * Input of `trace.graph` as `run` gets it: validated, properties with a `default` filled in. The graph of one element: what its links lead to above it and what links to it below, to a depth, over the chosen kinds, with each requirement's verification status.
 * Schema: `schemas/commands/trace.graph.json input`.
 */
export interface TraceGraphInput {
  readonly ref: ElementRef;
  /** The workspace name of the repository of the element ref names, as in element.get (ThomasBirkmaier/ReqSeq-archive#255). */
  readonly repository?: string;
  /** The deepest level in each direction; 0: the element only. Omitted: 1 (the direct neighbours), unless `allLevels` is true. */
  readonly maxDepth?: number;
  /** Go as far as the links go (the whole chain), within `limit`; not together with `maxDepth`. For the chain alone ask with `meanings: ["derivation"]`. */
  readonly allLevels: boolean;
  /** Keys of relation kinds or of properties of kind `relation` (such as `packages`) to follow. An unknown key is `input.invalid`. See `meanings` for the filter rule. */
  readonly kinds?: readonly Key[];
  /** Relation kinds with these meanings are followed; `reference` stands for inline references. Without `kinds` and `meanings` every relation and reference is followed. Otherwise a link is followed when its key is in `kinds` or its meaning is in `meanings`; an empty list follows nothing. */
  readonly meanings?: readonly ("derivation" | "replacement" | "succession" | "exclusion" | "reference")[];
  readonly view?: View;
  /** Also give `evidence`, a summary of the evidence (verification records and test cases) of each element shown below the element (SR-111 AK3). Evidence is no link between elements, so `kinds` and `meanings` do not choose it, and it is no node: `limit` counts the elements only. */
  readonly withEvidence: boolean;
  /** The most nodes, the element included; the nearest levels first (`truncated` says when more exist). */
  readonly limit: number;
}

/**
 * Output of `trace.graph`. The graph of one element: what its links lead to above it and what links to it below, to a depth, over the chosen kinds, with each requirement's verification status.
 * Schema: `schemas/commands/trace.graph.json output`.
 */
export interface TraceGraphOutput {
  readonly root: Uuid;
  /** Every element of the graph once: the element first, then level by level from the nearest (for each distance the elements above, then those below, each in the order the links were followed). An element reached both ways is one node at its smaller distance, above on a tie. In a view only the elements the view holds (SR-040, SR-043: not a core requirement the variant excludes or replaces); the element always. At most `limit` nodes. */
  readonly nodes: readonly {
    readonly id: Uuid;
    readonly shortId: ShortId;
    /** Its identifier (the value of its property with the meaning `identifier`, such as SR-036, ThomasBirkmaier/ReqSeq-archive#305), for display next to `shortId`; left out when it has none. */
    readonly identifier?: string;
    /** Key of its type. */
    readonly type: string;
    /** Its title; empty without one. */
    readonly title: string;
    /** Its status key as written; left out when it has none. */
    readonly status?: string;
    /** Workspace name of the repository of its file. */
    readonly repository: string;
    /** Path relative to the repository. */
    readonly file: string;
    /** Its links in the direction of its level (both for the element) were looked at and every element they lead to is a node. False at `maxDepth`, where `limit` stopped the walk, and when `limit` left out an element they lead to. */
    readonly expanded: boolean;
    /** 0 for the element; -d for an element reached d steps up along the links the files store (its parents, the targets of its other relations and relation properties, its inline references), +d for one reached d steps down along links that point at it. The source of a link is placed below its target (ADR-0004). */
    readonly level: number;
    /** In this order, only those that hold (SR-111 AK4): `outdated`, the element stores an outdated relation, relation property or inline reference (SR-025, the `relation.outdated` and `variant.core-changed` hints of element.get), whatever kinds are followed; `superseded`, its status is one the metamodel marks invalid (D-044). Empty when none holds. The verification status is `verification` (SR-136). */
    readonly marks: readonly ("outdated" | "superseded")[];
    /** SR-136 AK1: the verification status of a requirement (type with the meaning `requirement`) in the graph's view (`view`, the core without one; SR-031, SR-034), as element.get gives it for that view: one entry. Left out for any other node, and for a requirement that has no status in that view (it applies only in a variant; assumption, spec question #1111). */
    readonly verification?: readonly DataExportVerificationEntry[];
    /** SR-136 AK2, AK4, AK5: how many of the requirement's acceptance criteria are verified, for its progress ring: the entry's `criteria` when its own records in the view decide; without such a record and with acceptance criteria, none verified (0 of n); left out when the status is `indirect`, the requirement has no acceptance criteria, or it has no `verification`. */
    readonly criteria?: DataExportCriteriaCount;
    /** SR-136 AK3, AK6: for a need (type with the meaning `need`), the verification degree (SR-037) of the requirements derived directly from it, in the graph's view: its derivation children in the whole workspace whatever depth, kinds and meanings the graph shows, each once, counted as evidence.degree counts them. `share` is left out when none counts (no valid derived requirement). Without a relation kind with the meaning `derivation`, or while the metamodel is not valid, none counts. */
    readonly degree?: DataExportVerificationDegree;
  }[];
  /** Every followed link from one node to another, also one the walks did not take (a link between two parents, or from a child to a parent): by source in the order of `nodes`, then in the order its file stores them (relations and relation properties in frontmatter order, then inline references). A link from an element to itself is no edge. Not listed: unresolved links (`element.get` and `workspace.check` report them). */
  readonly edges: readonly {
    /** The element whose file stores the link. */
    readonly source: Uuid;
    /** Workspace name of the repository of `source`. */
    readonly sourceRepository: string;
    /** The element the link points at (ADR-0004). */
    readonly target: Uuid;
    /** Workspace name of the repository of `target`. */
    readonly targetRepository: string;
    /** A relation in the frontmatter or an inline reference in the text or in a property marked `markdown`. */
    readonly link: "relation" | "reference";
    /** The frontmatter key, only for `link: relation`. */
    readonly kind?: Key;
    /** The key is a property of kind `relation` (such as `packages`), not a relation kind. */
    readonly property?: true;
    /** The meaning of the relation kind, `reference` for an inline reference; left out for a kind without a meaning and for a property. */
    readonly meaning?: "derivation" | "replacement" | "succession" | "exclusion" | "reference";
    /** The link stores a version of normal form 1 or 2, its target has a current version, and the two differ, compared in the stored version's form (SR-025, ADR-0005). */
    readonly outdated: boolean;
  }[];
  /** Only with `withEvidence`: one summary of the evidence below each node that has any (SR-111 AK3), in the order of `nodes`; `[]` when none has. Only nodes at level 0 or below whose evidence level (`level`) is within the depth asked (`maxDepth`, every level with `allLevels`), whether `expanded` or not; none above the element. The counts are those of trace.chain's `evidence` (`chainEvidenceOf`) in the view, the core without one (SR-047, SR-173): only verification records (D-007). The details are in trace.chain and evidence.list. */
  readonly evidence?: readonly {
    /** The node the evidence belongs to. */
    readonly id: Uuid;
    /** Workspace name of the repository of that node. */
    readonly repository: string;
    /** The node's level plus one: the evidence is one level below it. */
    readonly level: number;
    /** The test cases that name the node and hold in the view, a test case that was only skipped included (SR-033 AK3). */
    readonly testCases: number;
    /** The node's verification records without a test case that hold in the view (inspection, analysis, demonstration, manual records without `test-case`). */
    readonly records: number;
    /** The newest result of each test case (`skipped` for one that was only skipped) and of each record, counted; a result none has is left out. */
    readonly results: {
      /** Test cases and records whose newest result passed. */
      readonly passed?: number;
      /** Test cases and records whose newest result failed. */
      readonly failed?: number;
      /** Test cases and records whose newest result is inconclusive. */
      readonly inconclusive?: number;
      /** Test cases that were only skipped. */
      readonly skipped?: number;
    };
  }[];
  /** More elements are reachable than shown: `limit` stopped a walk or left out a node. The nodes kept are the nearest ones. */
  readonly truncated: boolean;
  readonly incomplete: Incomplete;
  /** Hints: `metamodel.meaning-unassigned` when no relation kind has the meaning `derivation` or no type the meaning `requirement`, so the verification status and degree of the nodes cannot be given in full (SR-013 AK3). */
  readonly problems: readonly Problem[];
}

/**
 * Input of `hint.list` as `run` gets it: validated, properties with a `default` filled in. Open hints of the workspace, filterable by kind, type, package or variant; one page of hints at a time, total counts all.
 * Schema: `schemas/commands/hint.list.json input`.
 */
export interface HintListInput {
  /** Only hints with one of these codes. */
  readonly kind?: readonly ProblemCode[];
  /** Only hints about elements of one of these types, or of a type that extends one of them (SR-012). */
  readonly type?: readonly Key[];
  /** Only hints about elements whose property with the meaning packages lists this package. */
  readonly package?: ElementRef;
  /** Only hints about elements in the view of this variant (SR-043); a hint about a variant element only for that variant. */
  readonly variant?: ElementRef;
  /** Only the hints about this element. */
  readonly ref?: ElementRef;
  /** Hints of the page; total counts all. Every page finds every hint again; only the dates of outdated relations (D-013) are asked for the hints of the page alone. */
  readonly limit: number;
  /** Hints skipped before the page, in the order of `hints`. */
  readonly offset: number;
}

/**
 * Output of `hint.list`. Open hints of the workspace, filterable by kind, type, package or variant; one page of hints at a time, total counts all.
 * Schema: `schemas/commands/hint.list.json output`.
 */
export interface HintListOutput {
  /** The open hints: findings of severity warning about one element (the element should be checked; a hint blocks nothing and changes no status), from the same whole-workspace findings as workspace.check; errors, info and warnings about no element are not hints. Filters combine with AND. Each hint with its kind (code), the element it is about (elementId, repository, file, line), its target where it has one (targetId; with targetRepository, targetShortId and targetIdentifier when it was resolved to one element, #172) and its reason (message; for an outdated relation with both versions and their dates, D-013). In the order of workspace.check. Only the page of `limit` hints from `offset` (in this order) is listed; `total` counts every hint that passes the filters. */
  readonly hints: readonly Problem[];
  /** The number of all hints that pass the filters; `hints` holds the page of `limit` from `offset`. */
  readonly total: number;
  /** True while a repository of the workspace file is not on this machine: the hints of its elements are not listed (SR-006 AK2). */
  readonly incomplete: Incomplete;
}

/**
 * Input of `hint.confirm` as `run` gets it: validated, properties with a `default` filled in. Confirm hints after a person reviewed them, by ID (hintIds), all of one element (ref, target) or all of some codes (all with kind and expected): writes the current target version into the relation, the inline reference or the replaces item.
 * Schema: `schemas/commands/hint.confirm.json input`.
 */
export interface HintConfirmInput {
  /** IDs of hints to confirm (`hintId` of hint.list). */
  readonly hintIds?: readonly string[];
  /** Confirm the open confirmable hints about this element: the outdated relations and inline references (in the text and in properties marked `markdown`) its file stores, and its `replaces` items onto a changed core requirement. A variant with open `variant.core-changed-since-baseline` or `variant.core-new-since-baseline` hints, without `kind`, gives `hint.not-confirmable` for them, since a new baseline of the variant settles them (SR-103 AK5). */
  readonly ref?: ElementRef;
  /** Confirm the open confirmable hints on relations and inline references that point at this element, for example after it changed. */
  readonly target?: ElementRef;
  /** Select the open confirmable hints of the whole workspace with one of the codes of `kind`: those hint.list gives with a hintId for that `kind` and no other filter (#644). Needs `kind` with confirmable codes only (`relation.outdated`, `variant.core-changed`; a since-baseline code is refused with its reason, other codes are `input.invalid`) and `expected`; not with `ref` or `target`. */
  readonly all: boolean;
  /** Only selected hints with one of these codes (with `ref`, `target` or `all`); the confirmable codes are `relation.outdated` and `variant.core-changed`; `variant.core-changed-since-baseline` and `variant.core-new-since-baseline` give `hint.not-confirmable`, since a new baseline of the variant settles them (SR-103 AK5). */
  readonly kind?: readonly ProblemCode[];
  /** The number of hints the call confirms as the person reviewed them: the hints the selection holds, counted as hint.list counts them (a relation written twice is two hints with one ID), plus one per given hint ID that the selection does not hold (with `all`: `total` of hint.list with the same `kind` and no other filter). When the call would confirm another number, it is refused and nothing is written (`input.invalid`, details `count`), for example after a pull brought new hints. Required with `all`. */
  readonly expected?: number;
}

/**
 * Output of `hint.confirm`. Confirm hints after a person reviewed them, by ID (hintIds), all of one element (ref, target) or all of some codes (all with kind and expected): writes the current target version into the relation, the inline reference or the replaces item.
 * Schema: `schemas/commands/hint.confirm.json output`.
 */
export interface HintConfirmOutput {
  /** The IDs of the confirmed hints, each once. */
  readonly confirmed: readonly string[];
  /** Written files, relative to the workspace root. */
  readonly files: readonly string[];
  readonly problems?: readonly Problem[];
}

/**
 * Input of `element.search` as `run` gets it: validated, properties with a `default` filled in. Full-text search over title, text, properties and IDs of the elements of a selection, typo tolerant, in any case, the best first, each hit with where it was found and a snippet around the match; optionally in groups.
 * Schema: `schemas/commands/element.search.json input`.
 */
export interface ElementSearchInput {
  /** Words split at spaces; every word must match (in the title, the text, a property value, the type or status name, or an ID). A word matches words it begins (from 2 letters) and with a typo (1 edit from 4 letters, 2 from 8; none for a query word with a digit), in any case. A short ID, an identifier or at least 6 hex digits of a UUID match that element exactly; ID matches come first. A query without a word finds nothing. */
  readonly query: string;
  /** Search only within it (SR-068 AK3): a view, a filter, a package or IDs. */
  readonly selection?: ElementSelection;
  /** Search only these: `title`, `text` (the Markdown text), `properties` (every other value, type and status names; not relations), `id` (UUID, short ID, identifier). Default all. */
  readonly fields?: readonly ("title" | "text" | "properties" | "id")[];
  /** Group the hits (SR-149 AK6) by the keys and rules of element.list `group`: the same groups in the same order, a hit with several values in each of their groups, the hits without a value (or with only targets not available) in the last group, and an invalid key `input.invalid` whatever the query finds. Inside each group the hits keep the order of the search (ID matches, then relevance, then workspace order). The grouping reads the records the hits were found in; their targets are looked up in the workspace the selection was read from. Nothing is stored. */
  readonly group?: GroupKey;
  /** Also give what each row shows of its element's verification (SR-137), in `rowVerification`. */
  readonly withVerification?: boolean;
  /** The most hits on one page. */
  readonly limit: number;
  /** Hits skipped before the page. */
  readonly offset: number;
}

/**
 * Output of `element.search`. Full-text search over title, text, properties and IDs of the elements of a selection, typo tolerant, in any case, the best first, each hit with where it was found and a snippet around the match; optionally in groups.
 * Schema: `schemas/commands/element.search.json output`.
 */
export interface ElementSearchOutput {
  /** One page of the hits. With `group`, the page of the grouped rows (the hits of the first group, then of the next): a hit in several groups is a row in each, so a page can hold it more than once; key the rows by their position, not by the element. */
  readonly hits: readonly {
    readonly id: Uuid;
    /** Workspace name of the repository of the element. */
    readonly repository: string;
    readonly shortId: ShortId;
    /** The value of the property with the meaning identifier, when the element has one. */
    readonly identifier?: string;
    readonly type: Key;
    /** The status key as written in the file. */
    readonly status?: string;
    /** Empty without a title. */
    readonly title: string;
    /** Relevance of the matched words, rounded to 6 significant digits; 0 for an ID match only. */
    readonly score: number;
    /** What a word of the query was found in. */
    readonly fields: readonly ("title" | "text" | "properties" | "id")[];
    /** The words of the element that matched, in lower case, for highlighting; none for an ID. */
    readonly terms: readonly string[];
    /** The matched words in `title` (SR-174 AK4); only when a word was found in the title. */
    readonly titleMarks?: TextMarks;
    /** Where a word was found and one line around the first match in reading order (SR-174): in the text when a visible word of it matched, else in the first property value with a match, the properties of the type in metamodel order, then the others in file order. `text` is at most 120 code points, `…` at a cut end included: the visible text without Markdown characters, white space as single spaces; `marks` are the matched words in it. A list item or a nested value is a value of its own; a choice shows its name. None when no visible word matched: a match only in the title, an ID, the identifier, the type or status name, a link destination, HTML or an entity, or a file changed since the index read it. */
    readonly snippet?:
      | {
        readonly field: "text";
        readonly text: string;
        readonly marks: TextMarks;
      }
      | {
        readonly field: "properties";
        /** The frontmatter key. */
        readonly property: string;
        /** Its name in the metamodel; the key for a property the metamodel does not define. */
        readonly propertyName: string;
        readonly text: string;
        readonly marks: TextMarks;
      };
  }[];
  /** Only with `group`: every group of all the hits in order, also those on other pages; a group without hits is not given. `offset` and `rows` follow from the counts. */
  readonly groups?: readonly ListGroup[];
  /** Only with `group`: the row the page starts at (the `offset` of the input). */
  readonly offset?: number;
  /** Only with `group`: the rows of the grouped hits, the sum of the counts of `groups`; `offset` and `limit` page over these rows. At least `total`, more when hits are in several groups. */
  readonly rows?: number;
  /** Only with `withVerification`: for each row of `hits`, in the same order, the verification status of a requirement and the progress ring of a requirement or need, as a node of trace.graph carries them (SR-137 AK1, AK3). */
  readonly rowVerification?: readonly DataExportRowVerification[];
  /** Hits, each once. */
  readonly total: number;
  readonly incomplete: Incomplete;
}

/**
 * Input of `filter.list` as `run` gets it: validated, properties with a `default` filled in. Saved filters of the workspace, with their definitions.
 * Schema: `schemas/commands/filter.list.json input`.
 */
export type FilterListInput = Readonly<Record<string, never>>;

/**
 * Output of `filter.list`. Saved filters of the workspace, with their definitions.
 * Schema: `schemas/commands/filter.list.json output`.
 */
export interface FilterListOutput {
  /** In the order of their files. A faulty file is not listed; it is one of `problems`. */
  readonly filters: readonly {
    readonly name: FilterName;
    /** The filter file, relative to the workspace root. */
    readonly file: string;
    /** What the filter is for, as saved. */
    readonly description?: string;
    readonly view?: View;
    readonly where: FilterCondition;
    readonly sort?: readonly FilterSortKey[];
  }[];
  /** Filter files that cannot be read, do not match filter.schema.json, or repeat the name of an earlier file. */
  readonly problems?: readonly Problem[];
  readonly incomplete?: Incomplete;
}

/**
 * Input of `filter.save` as `run` gets it: validated, properties with a `default` filled in. Save a named filter as YAML in the repository; an existing name replaces that filter.
 * Schema: `schemas/commands/filter.save.json input`.
 */
export interface FilterSaveInput {
  readonly name: FilterName;
  /** What the filter is for, for people. */
  readonly description?: string;
  readonly view?: View;
  /** Checked as in a selection; element references are written as UUIDs. */
  readonly where: FilterCondition;
  /** Order of element.list with this filter when its input gives no sort. */
  readonly sort?: readonly FilterSortKeyWithDefaults[];
}

/**
 * Output of `filter.save`. Save a named filter as YAML in the repository; an existing name replaces that filter.
 * Schema: `schemas/commands/filter.save.json output`.
 */
export interface FilterSaveOutput {
  readonly files: readonly string[];
  readonly problems?: readonly Problem[];
}

/**
 * Input of `evidence.list` as `run` gets it: validated, properties with a `default` filled in. Evidence records of an element with version, item, date, result, evidence location and baselines that contain the version.
 * Schema: `schemas/commands/evidence.list.json input`.
 */
export interface EvidenceListInput {
  readonly ref: ElementRef;
  /** `core`: only the records without a variant; a variant: only the records for that variant (SR-047 AK1, AK2), and also those without a variant when the element's repository is marked `variant-independent` (SR-173); absent: every record of the element. */
  readonly view?: View;
  /** Which of the elements ref names is meant: the workspace name of its repository, as details.candidates of ref.ambiguous give it (for example one copy of a file whose UUID another file shares, SR-088; ThomasBirkmaier/ReqSeq-archive#255). Only the elements ref names count; when none of them lies there, the error is ref.unknown with them as details.candidates. */
  readonly repository?: string;
  /** Which of the elements ref names is meant: its file, relative to its repository, as details.candidates of ref.ambiguous give it (ThomasBirkmaier/ReqSeq-archive#255). Give repository too when the same path is in several repositories; when several elements are still left, the error is ref.ambiguous with them. */
  readonly file?: RelativePath;
}

/**
 * Output of `evidence.list`. Evidence records of an element with version, item, date, result, evidence location and baselines that contain the version.
 * Schema: `schemas/commands/evidence.list.json output`.
 */
export interface EvidenceListOutput {
  /** The evidence records of the element (SR-028, SR-093), newest first, each with its version, item, date, result and evidence (SR-032 AK1) and the baselines that contain its version (`baselines`, SR-032 AK2; empty when none does). */
  readonly records: readonly DataExportEvidenceRecord[];
  /** The positions in `records` (from 0, ascending) of the records that bear the element's status (SR-032 AK3): per kind, variant and acceptance criterion (D-072) every record with the newest date of the current version, else every one with the newest date of an older version, so the whole run of a CI stays open; a record without criteria counts for every criterion (SR-031 AK6). In a repository marked `variant-independent` (SR-173) a variant's records are pooled with those without variant, as its status pools them. The app shows these open and folds the others away. */
  readonly bearing: readonly number[];
  /** The Evidence section at a glance (SR-032 AK3 to AK5), computed in core so every access gives the same: the values the bearing records share, one row per acceptance criterion (and one for the validation), and the other records by run. */
  readonly display: {
    /** AK5: each of date, item, version and baselines that every bearing record has with the same value (a date as the same instant, the first record's text); left out otherwise. */
    readonly shared: {
      readonly date?: IsoDateTime;
      /** The item under test that every shown record names. */
      readonly item?: string;
      readonly version?: Version;
      /** The baselines every shown record names, in the same order. */
      readonly baselines?: readonly string[];
    };
    /** AK4: with a verification record, one row per acceptance criterion 1..n (one without `criterion` for a requirement without criteria); with a validation record of a need or a requirement, one validation row after them (SR-038 AK5). */
    readonly rows: readonly {
      /** Whether the row shows verification or validation records. */
      readonly kind: "verification" | "validation";
      /** The acceptance criterion, counted from 1; left out for a requirement without criteria and for the validation row. */
      readonly criterion?: number;
      /** Verification: the worst status of `views` (failed before outdated before open before verified). Validation: the validation status (SR-038). */
      readonly status: "open" | "verified" | "failed" | "outdated" | "validated" | "inconclusive";
      /** Verification only: the status of the criterion in each view the element applies in, without that of a variant whose status the metamodel marks invalid (SR-031, SR-047 AK6; with `view`, that view alone, also such a variant's), the core first; the app names those whose status is the row's. While the metamodel is not valid the status shows every requirement open, but these statuses still compare the records. */
      readonly views?: readonly {
        /** `core` or the variant's UUID. */
        readonly view: string;
        readonly status: "open" | "verified" | "failed" | "outdated";
      }[];
      /** The bearing records of the row (those naming the criterion or none, SR-031 AK6) by test case: worst result first, then class name, then name in code-unit order, records without test case last in their order. */
      readonly cases: readonly {
        /** The test case's name; left out for a record without test case. */
        readonly testCase?: string;
        /** The JUnit class name; left out for a Markdown record or a record without test case. */
        readonly className?: string;
        /** The worst result of its records: failed before inconclusive before passed. */
        readonly result: "passed" | "failed" | "inconclusive";
        /** The views its records hold for: `core` for a record without variant, else the variant's UUID; `core` first, then the UUIDs in code-unit order. */
        readonly views: readonly string[];
        /** Its records, positions in `records`, in their order. */
        readonly records: readonly number[];
      }[];
    }[];
    /** AK3: the records outside `bearing` by run (the same date as an instant and the same version), newest first, then version in code-unit order. Records that name only criteria beyond the count bear nothing and are here. */
    readonly older: readonly {
      readonly date: IsoDateTime;
      readonly version: Version;
      /** Its records, positions in `records`, in their order. */
      readonly records: readonly number[];
    }[];
  };
  /** The test cases that name the element (SR-033), by class name, then name, each with the element's own records only, newest first, and every kind of record as in `records`; with `view` only the executions that hold in it, and a test case all of whose executions hold in another view is left out (a test case that was only skipped stays, `executed` false). */
  readonly testCases: readonly DataExportTestCase[];
  /** Findings in the baseline files (`baseline.invalid`, `file.invalid-yaml`, ...): a baseline file that cannot be read names no baseline in `baselines`. */
  readonly problems: readonly Problem[];
  /** True when an evidence location or the baselines folder lies in a repository that is not on this machine: records or baselines there are not seen (SR-006 AK2). */
  readonly incomplete: Incomplete;
}

/**
 * Input of `evidence.record` as `run` gets it: validated, properties with a `default` filled in. Write a manual verification or validation record into an evidence folder of the workspace, for a check that is not an automated test; the element's UUID and current version are filled in.
 * Schema: `schemas/commands/evidence.record.json input`.
 */
export interface EvidenceRecordInput {
  /** The element the record is about. Its UUID and current version are written into the record; neither is an input (D-026). */
  readonly ref: ElementRef;
  /** Verification of a requirement, or validation of a need or a requirement (D-007, D-012). A validation record counts for the validation status only (SR-030 AK3). */
  readonly kind: "verification" | "validation";
  /** Required for verification. */
  readonly method?: "test" | "analysis" | "inspection" | "demonstration";
  /** The result of the check. `inconclusive` is allowed for a validation only and needs a `reason` (SR-172 AK1). */
  readonly result: "passed" | "failed" | "inconclusive";
  /** Why the validation is inconclusive (SR-172): required with the result `inconclusive`, not allowed with any other result. At least one character that is not white space, no control characters other than tab, line feed and carriage return. */
  readonly reason?: string;
  /** The item under test, for example the build or sample. Required for verification. No white space at either end and no control characters other than tab, line feed and carriage return. */
  readonly item?: Item;
  /** A variant the element applies in (an element whose type has the meaning variant); the record holds for it. Absent: the core, and also every variant the element applies in when the element's repository is marked `variant-independent` in the workspace file (SR-173). Verification only: a variant with `kind` validation is `input.invalid` with `details.reason` `validation-with-variant` (SR-038 AK4, D-007). `core` names no variant and is `input.invalid` with `details.reason` `core-is-no-variant`; leave `variant` out for the core. A variant the element is not in is `input.invalid` with `details.reason` `not-valid-in-variant`, or `excluded-in-variant` or `replaced-in-variant` when the variant excludes or replaces the requirement (SR-047 AK4). Absent for a verification of an element the core does not hold, which would then count in no view, is `input.invalid` with `details.reason` `counts-in-no-view` (SR-047 AK5), unless the element's repository is marked `variant-independent` and a variant holds it (SR-173). */
  readonly variant?: ElementRef;
  /** When the check was done. Default: the time of the call, UTC, whole seconds. Its first ten characters (the day in its own offset) start the file name. */
  readonly date?: IsoDateTime;
  /** Where the evidence is: a path relative to the record file, a file URL or any URI. Written as given; ReqSeq never opens it (D-007). */
  readonly evidence?: string;
  /** Optional test case name or ID (`test-case` in the file, SR-033). */
  readonly testCase?: string;
  /** The acceptance criteria the record holds for, by number: the position in the property with the meaning `acceptance-criteria` of the element's current version, counted from 1 (D-072, SR-030 AK4), at most 9007199254740991 (the largest whole number JSON readers keep exactly, so the file holds the number as given). Written in ascending order as `criteria` of the file. Absent: the record holds for every criterion. Verification only: with `kind` validation it is `input.invalid` with `details.reason` `validation-with-criteria`, because a validation counts per element (SR-030 AK3). A number the current version does not have is written and gives the warning `evidence.unknown-criterion` in `problems` (SR-028 AK5). */
  readonly criteria?: readonly number[];
  /** The folder to write into: an evidence location of the workspace file or a folder below one, relative to the workspace root (the folder of the main repository) with `/`, for example `evidence/manual` or `../tests/evidence`. Missing folders below the location are created. Default: the first evidence location whose repository is on this machine. */
  readonly folder?: string;
}

/**
 * Output of `evidence.record`. Write a manual verification or validation record into an evidence folder of the workspace, for a check that is not an automated test; the element's UUID and current version are filled in.
 * Schema: `schemas/commands/evidence.record.json output`.
 */
export interface EvidenceRecordOutput {
  readonly files: readonly string[];
  /** The record as the Markdown reader reads it back from the written file (`source: markdown`, its repository and file, line 1), with the UUID and current version of the element. */
  readonly record: DataExportEvidenceRecord;
  readonly problems?: readonly Problem[];
}

/**
 * Input of `evidence.enrichJunit` as `run` gets it: validated, properties with a `default` filled in. Tie the test cases of a JUnit XML file to the elements they name, adding UUID, version, item, date and the views run, so the file is test evidence. Test cases with an unknown reference or a view that does not fit are listed, and the CLI exits 1.
 * Schema: `schemas/commands/evidence.enrichJunit.json input`.
 */
export interface EvidenceEnrichJunitInput {
  /** The JUnit XML file to enrich. It is rewritten in place unless `output` is given. A test case that already has a `reqseq:version` is never changed (D-026: version from the tested state; spec question ThomasBirkmaier/ReqSeq-archive#529 Q5). */
  readonly file: LocalPath;
  /** The item under test, for example the build. No white space at either end and no control characters other than tab, line feed and carriage return. */
  readonly item: Item;
  /** The date of the test run. Default: an existing `reqseq:date` of the test case, else the `timestamp` of its test suite when that has a time zone, else the time of the call. */
  readonly date?: IsoDateTime;
  /** The views the test run was for, one or more: a variant by UUID, short ID or identifier, or `core` (SR-029 AK6). Each enriched test case gets a `reqseq:variant` per view, the variant's UUID or `core`; the core alone writes none. Absent: a test case keeps its own `reqseq:variant` properties, if any, whose short ID or identifier becomes the UUID. A test case that names a view not given (AK8), or names an element that does not count in one of its views (not valid there, excluded or replaced, as at `evidence.record`, AK9), stays unchanged and gets `evidence.invalid-record`; so does an enriched test case (never changed, D-026: version from the tested state; spec question ThomasBirkmaier/ReqSeq-archive#529 Q5) with a view not given. The core is checked like a variant when it is given or named; a record without variant counts in the core, and in every view the element applies in when its repository is marked `variant-independent` (SR-173). */
  readonly variant?: readonly View[];
  /** Only with `variant` (else `input.invalid` with `details.reason` `skip-without-views`): an element that applies in none of the given views is left out of the test case instead of refusing it (SR-029 AK11): it gets no `reqseq:element`, `reqseq:version` or `reqseq:criterion`, and `notInView` counts these. A test case with no element left gets no requirement but one `reqseq:not-in-view` property per given view, the variant's UUID or `core`, in the order given (AK12); its name and other properties stay. A run with the same views leaves such a mark as it is, one with other views rewrites it, and a run that enriches the test case removes it. The JUnit reader passes over a marked test case without `evidence.not-enriched` (SR-093 AK6). An element that applies in some of them is enriched, and its records count only where it applies. Default false: such a test case stays unchanged and is reported (AK9). */
  readonly skipNotInView?: boolean;
  /** A template that finds a short ID written in another form in test case names, for names that cannot hold brackets, e.g. `{prefix}_{id}_ak{ak}` for `sr_348143_ak1` (SR-348143). `{prefix}` is a type prefix of the metamodel, `{id}` 6 to 32 hex digits, `{ak}` 1 to 9 digits, the number of the acceptance criterion written as `reqseq:criterion` (from 1 without leading zero, else the test case is not enriched); `{prefix}` and `{id}` once each, `{ak}` once at most and not next to `{id}`. The rest is literal text; `{{` and `}}` are braces, square brackets are refused. All of it is ASCII case-insensitive. A match starts and ends at a word boundary (the start or end of the name, a character that is not a letter or digit, or the start of a camel case word) and is looked for in the name outside `[...]` only, not in the class name. It adds to the bracket form and the `reqseq:element` property; a short ID it finds that names no element, or several, is listed in `unknown`. */
  readonly namePattern?: string;
  /** Default: overwrite the input file. An existing file is replaced only when it is a JUnit XML file the scanner accepts; its folder must exist. */
  readonly output?: LocalPath;
}

/**
 * Output of `evidence.enrichJunit`. Tie the test cases of a JUnit XML file to the elements they name, adding UUID, version, item, date and the views run, so the file is test evidence. Test cases with an unknown reference or a view that does not fit are listed, and the CLI exits 1.
 * Schema: `schemas/commands/evidence.enrichJunit.json output`.
 */
export interface EvidenceEnrichJunitOutput {
  /** The test cases that name at least one element and are enriched: by this call, or already before. */
  readonly testCases: number;
  /** The test cases that name no element: no `reqseq:element` property and no name token or pattern match that names one (a pytest parameter list counts here). Test cases enriched already, listed in `unknown` or refused are not counted. Information only: it does not change the exit code. */
  readonly withoutReference: number;
  /** With `skipNotInView`: the elements left out of a test case because they apply in none of the given views, counted once per test case and element (SR-029 AK11); a test case with no element left is marked (AK12, see `skipNotInView`). Information only: it does not change the exit code. */
  readonly notInView: number;
  /** Each reference that names no element or more than one, with its test case; that test case stays unchanged. */
  readonly unknown: readonly {
    /** The `name` of the test case. */
    readonly testCase: string;
    /** The `classname` of the test case. */
    readonly className?: string;
    /** The line of the `<testcase>` in the file as read. */
    readonly line: number;
    /** The reference as the test case gives it. */
    readonly ref: string;
  }[];
  /** The written file, relative to the workspace root (the folder of the main repository) with `/` when it lies below it or in another repository of the workspace, else its absolute path. None when nothing is written: nothing to change in place, or `output` holds these bytes already; a given `output` is otherwise written even when nothing changes. */
  readonly files: readonly string[];
  readonly problems: readonly Problem[];
}

/**
 * Input of `evidence.status` as `run` gets it: validated, properties with a `default` filled in. Verification status of a selection per view, from the evidence records and, without own record, from the children; validation status from the validation records.
 * Schema: `schemas/commands/evidence.status.json input`.
 */
export interface EvidenceStatusInput {
  readonly selection?: ElementSelection;
  /** The most elements on one page. */
  readonly limit: number;
  /** Elements skipped before the page. */
  readonly offset: number;
}

/**
 * Output of `evidence.status`. Verification status of a selection per view, from the evidence records and, without own record, from the children; validation status from the validation records.
 * Schema: `schemas/commands/evidence.status.json output`.
 */
export interface EvidenceStatusOutput {
  /** One page of the selection in workspace order, each element as element.list gives it, with `verification` for every element whose type has the meaning `requirement`: its verification status (SR-031, ADR-0012 "Status rules") in each view it is in by the view rule: the core when it has no validity, each variant it is in; none for a variant that excludes or replaces it (SR-043, SR-047 AK3) or whose status the metamodel marks invalid (SR-047 AK6), and for a requirement without own verification record in a view its indirect verification from its children (`indirect`) or the children that are missing (`missingChildren`, SR-034); an element marked emergent (SR-035) is never `indirect`; and `validation`, the validation status (SR-038, `$defs/element` `validation`: every need, a requirement with a validation record). Derived from the evidence records; it is not the element's `status` and never changes it (D-030). While the metamodel is not valid the records are not compared: every requirement is `open`, every need `open`, and no other element has `validation`. */
  readonly elements: readonly DataExportElement[];
  /** Every element of the selection, not only the page. */
  readonly total: number;
  /** A repository of the workspace is not available here (SR-006 AK2): its elements, and the records of its evidence locations, are missing. */
  readonly incomplete?: Incomplete;
  /** The elements that `verification` names by UUID only, each once in the order first named: the variants of its views and the missing children (`missingChildren`), so a reader names them by short ID, identifier and title (ThomasBirkmaier/ReqSeq-archive#588). Left out when it names none. */
  readonly names?: readonly ElementName[];
}

/**
 * Input of `evidence.coverage` as `run` gets it: validated, properties with a `default` filled in. Coverage of a selection per level: how many have children, how many have evidence; with the element lists.
 * Schema: `schemas/commands/evidence.coverage.json input`.
 */
export interface EvidenceCoverageInput {
  /** The elements to cover, as `element.list` takes them; every part given must hold (SR-101 AK2). Its view (else the view of its saved filter, else the core, SR-036 AK5) narrows the counted elements and their children to those it holds (SR-043: no core requirement the variant excludes or replaces), and evidence records count for that view, as the filter condition `verification` does. */
  readonly selection?: ElementSelection;
}

/**
 * Output of `evidence.coverage`. Coverage of a selection per level: how many have children, how many have evidence; with the element lists.
 * Schema: `schemas/commands/evidence.coverage.json output`.
 */
export interface EvidenceCoverageOutput {
  /** One level per element type of the selection with the meaning `need` or `requirement` (a subtype is its own level), in metamodel order (spec question ThomasBirkmaier/ReqSeq-archive#527). Elements whose status the metamodel marks invalid are not counted (SR-036 AK4, D-044); other types have no level. */
  readonly levels: readonly {
    readonly type: Key;
    /** The counted elements of the type. */
    readonly total: number;
    /** How many have a derivation child that counts: one whose status is not marked invalid and, with a view, that applies in it; in any repository. */
    readonly withChildren: number;
    /** Only for a type with the meaning `requirement`: how many have at least one verification record in the view (the core without one), of any version and result (`hasVerificationRecord`, spec question ThomasBirkmaier/ReqSeq-archive#527). */
    readonly withEvidence?: number;
    /** The UUIDs behind every number, in selection order (SR-036 AK2): pass them as `selection.ids` to `element.list`. `withEvidence` and `withoutEvidence` only where the level has `withEvidence`. */
    readonly elements: {
      readonly withChildren: readonly Uuid[];
      readonly withoutChildren: readonly Uuid[];
      readonly withEvidence?: readonly Uuid[];
      readonly withoutEvidence?: readonly Uuid[];
    };
  }[];
  readonly incomplete?: Incomplete;
  /** Every element of `levels[].elements`, each once in selection order, so a reader names them by short ID, identifier and title (ThomasBirkmaier/ReqSeq-archive#588). Left out when no level lists an element. */
  readonly names?: readonly ElementName[];
}

/**
 * Input of `evidence.degree` as `run` gets it: validated, properties with a `default` filled in. Verification degree of a selection in one view: the share of the requirements verified or indirect, and the count per verification status (SR-037).
 * Schema: `schemas/commands/evidence.degree.json input`.
 */
export interface EvidenceDegreeInput {
  /** The requirements to count, as element.list takes them. Its view (else its saved filter's, else the core) is the view of the status. */
  readonly selection?: ElementSelection;
}

/**
 * Output of `evidence.degree`. Verification degree of a selection in one view: the share of the requirements verified or indirect, and the count per verification status (SR-037).
 * Schema: `schemas/commands/evidence.degree.json output`.
 */
export interface EvidenceDegreeOutput {
  readonly degree: DataExportVerificationDegree;
  /** core, or the variant of the selection's view (else of its saved filter's). */
  readonly view: ViewId;
  readonly incomplete?: Incomplete;
  /** The variant of `view` (ThomasBirkmaier/ReqSeq-archive#588), so a reader names it by short ID and title. Left out in the core. */
  readonly names?: readonly ElementName[];
}

/**
 * Input of `evidence.withoutPassedTest` as `run` gets it: validated, properties with a `default` filled in. Every requirement without a passed test execution in one view (SR-120): no verification record with method test and result passed, of any version, holds there (spec question ThomasBirkmaier/ReqSeq-archive#532). Each with its verification status.
 * Schema: `schemas/commands/evidence.withoutPassedTest.json input`.
 */
export interface EvidenceWithoutPassedTestInput {
  /** Default: the core. A variant: only records for it count, and those without a variant for an element of a repository marked `variant-independent` (SR-173); only requirements its view holds (SR-047, SR-043). */
  readonly view?: View;
  /** The most requirements on one page. */
  readonly limit: number;
  /** Requirements skipped before the page. */
  readonly offset: number;
}

/**
 * Output of `evidence.withoutPassedTest`. Every requirement without a passed test execution in one view (SR-120): no verification record with method test and result passed, of any version, holds there (spec question ThomasBirkmaier/ReqSeq-archive#532). Each with its verification status.
 * Schema: `schemas/commands/evidence.withoutPassedTest.json output`.
 */
export interface EvidenceWithoutPassedTestOutput {
  /** One page, by type, then identifier, else short ID: every requirement (type with the meaning `requirement`, status not marked invalid, applies in the view) without a verification record with method `test` and result `passed` that holds in the view, of any version and also when a later run failed (spec question ThomasBirkmaier/ReqSeq-archive#532). Each as evidence.status gives it, with `verification` and `validation`. */
  readonly elements: readonly DataExportElement[];
  /** Every listed requirement, not only the page. */
  readonly total: number;
  /** core, or the variant of the view. */
  readonly view: ViewId;
  /** A repository of the workspace, or of an evidence location, is not on this machine: its requirements, or a passed test there, are not seen (SR-006 AK2). */
  readonly incomplete?: Incomplete;
  /** The elements that `verification` names by UUID only, each once in the order first named: the variant of the view and the missing children (`missingChildren`), so a reader names them by short ID, identifier and title (ThomasBirkmaier/ReqSeq-archive#588). Left out when it names none. */
  readonly names?: readonly ElementName[];
}

/**
 * Input of `data.export` as `run` gets it: validated, properties with a `default` filled in. Data of the current state as JSON for external evaluation, or, from the command line and the API, as JSON Lines with one element per line; a selection narrows it.
 * Schema: `schemas/commands/data.export.json input`.
 */
export interface DataExportInput {
  readonly selection?: ElementSelection;
}

/**
 * Output of `data.export`. Data of the current state as JSON for external evaluation, or, from the command line and the API, as JSON Lines with one element per line; a selection narrows it.
 * Schema: `schemas/commands/data.export.json output`.
 */
export type DataExportOutput = DataExportFile & Readonly<Record<string, unknown>>;

/**
 * Input of `data.store` as `run` gets it: validated, properties with a `default` filled in. Write the data of the current state as JSON Lines to `<commit>.jsonl` in a folder, so that many states load as one table.
 * Schema: `schemas/commands/data.store.json input`.
 */
export interface DataStoreInput {
  /** Folder for the file; created when missing inside a repository of the workspace (also an ignored one), must exist outside. */
  readonly folder: LocalPath;
  readonly selection?: ElementSelection;
}

/**
 * Output of `data.store`. Write the data of the current state as JSON Lines to `<commit>.jsonl` in a folder, so that many states load as one table.
 * Schema: `schemas/commands/data.store.json output`.
 */
export interface DataStoreOutput {
  readonly files: readonly string[];
  readonly problems?: readonly Problem[];
}

/**
 * Input of `variant.diff` as `run` gets it: validated, properties with a `default` filled in. What a variant adds, replaces and excludes compared to the core.
 * Schema: `schemas/commands/variant.diff.json input`.
 */
export interface VariantDiffInput {
  /** The variant. An element whose type has no meaning `variant` is `input.invalid` with `details.reason: "not-a-variant"`; an unknown or ambiguous reference is `ref.unknown` or `ref.ambiguous`. */
  readonly variant: ElementRef;
}

/**
 * Output of `variant.diff`. What a variant adds, replaces and excludes compared to the core.
 * Schema: `schemas/commands/variant.diff.json output`.
 */
export interface VariantDiffOutput {
  /** Requirements whose validity names the variant and that replace no core requirement that is not excluded in it (SR-044 AK1), also the source of a replaces onto an element that is no core requirement (SR-041 AK8). Store order. */
  readonly added: readonly Uuid[];
  /** One row per pair, in store order of the core requirement, then of the replacement: two replacements of one core requirement are two rows (SR-041 AK7). A core requirement that is also excluded is not here (SR-042 AK5). */
  readonly replaced: readonly {
    readonly core: Uuid;
    readonly replacement: Uuid;
  }[];
  /** Core requirements the variant excludes, also when replaced too; store order. */
  readonly excluded: readonly Uuid[];
  /** Every element the lists name, each once, in order first named (ThomasBirkmaier/ReqSeq-archive#588). Left out when it names none. */
  readonly names?: readonly ElementName[];
  /** The variant.target-not-core hints of the variant's own entries and of its replacements. */
  readonly problems?: readonly Problem[];
  /** A repository is not here: a replacement or exclusion stored there is missing (SR-006 AK2). */
  readonly incomplete?: Incomplete;
}

/**
 * Input of `variant.exclude` as `run` gets it: validated, properties with a `default` filled in. Exclude core requirements for a variant; written into the variant file only.
 * Schema: `schemas/commands/variant.exclude.json input`.
 */
export interface VariantExcludeInput {
  /** The variant. An element whose type has no meaning `variant` is `input.invalid` with `details.reason: "not-a-variant"`; an unknown or ambiguous reference is `ref.unknown` or `ref.ambiguous`. */
  readonly variant: ElementRef;
  /** The core requirements to exclude, or with `undo` whose exclusion to remove. Adding an exclusion of a requirement with a validity, a need or a package is refused (SR-042 AK4): `input.invalid` with `details.reason: "not-core"` and `details.refs` (the refused refs); nothing is written. With `undo` every exclusion entry that is there is removed, also one of no core requirement (SR-042 AK7). */
  readonly refs: readonly ElementRef[];
  /** Remove the exclusions of `refs` instead. An exclusion that is not there is an `info` problem `relation.not-found` in `problems`, as relation.remove gives it; the other refs are undone. */
  readonly undo: boolean;
}

/**
 * Output of `variant.exclude`. Exclude core requirements for a variant; written into the variant file only.
 * Schema: `schemas/commands/variant.exclude.json output`.
 */
export interface VariantExcludeOutput {
  readonly files: readonly string[];
  readonly problems?: readonly Problem[];
}

/**
 * Input of `baseline.create` as `run` gets it: validated, properties with a `default` filled in. Write a baseline file for a selection (SR-050, ADR-0018): name, date, the HEAD commit of every repository involved, ID and version (in normal form n2, ADR-0005) of every element. Refused while files of the selection are not committed. Never commits, never replaces a baseline.
 * Schema: `schemas/commands/baseline.create.json input`.
 */
export interface BaselineCreateInput {
  readonly name: BaselineName;
  /** Stored in the file: a saved filter as its where and view, package and view with their title. Not baseline. */
  readonly selection: ElementSelection;
}

/**
 * Output of `baseline.create`. Write a baseline file for a selection (SR-050, ADR-0018): name, date, the HEAD commit of every repository involved, ID and version (in normal form n2, ADR-0005) of every element. Refused while files of the selection are not committed. Never commits, never replaces a baseline.
 * Schema: `schemas/commands/baseline.create.json output`.
 */
export interface BaselineCreateOutput {
  readonly files: readonly string[];
  /** The written baseline. */
  readonly baseline: {
    /** Name of the baseline. */
    readonly name: string;
    /** The file, relative to the workspace root, / as separator. */
    readonly file: string;
    /** The repository that holds the file; `repository` in the file is relative to it. */
    readonly repository: string;
    readonly date: IsoDateTime;
    /** Number of elements in the file. */
    readonly elements: number;
  };
  readonly problems?: readonly Problem[];
  /** A repository is not here, so the view may miss a replacement or exclusion stored there (SR-006); the file is written all the same, with a warning. */
  readonly incomplete?: Incomplete;
}

/**
 * Input of `baseline.list` as `run` gets it: validated, properties with a `default` filled in. Baseline files of the workspace, with name, date, view and number of elements (ADR-0018).
 * Schema: `schemas/commands/baseline.list.json input`.
 */
export type BaselineListInput = Readonly<Record<string, never>>;

/**
 * Output of `baseline.list`. Baseline files of the workspace, with name, date, view and number of elements (ADR-0018).
 * Schema: `schemas/commands/baseline.list.json output`.
 */
export interface BaselineListOutput {
  /** The valid baselines, in file order (code units of the file name). */
  readonly baselines: readonly {
    /** Name of the baseline. */
    readonly name: string;
    /** Relative to the workspace root, / as separator. */
    readonly file: string;
    /** The repository that holds the file. */
    readonly repository: string;
    readonly date: IsoDateTime;
    /** The variant whose baseline it is: its stored selection is only that view (SR-103 AK4). Left out otherwise. */
    readonly view?: ViewId;
    /** Number of elements in the file. */
    readonly elements: number;
  }[];
  /** The baselines folder: the workspace file's `baselines`, or `baselines` in the main repository. */
  readonly location: WorkspaceLocation;
  /** baseline.invalid of the files that are no valid baseline. */
  readonly problems?: readonly Problem[];
  /** The repository of the baselines folder is not here, so its baselines are not seen (SR-006 AK2). */
  readonly incomplete?: Incomplete;
}

/**
 * Input of `baseline.get` as `run` gets it: validated, properties with a `default` filled in. The elements of a baseline with their version then and its date, each marked changed, superseded, removed or added since (SR-051); with withEvidence also the verification and validation status at their version in the baseline (SR-094).
 * Schema: `schemas/commands/baseline.get.json input`.
 */
export interface BaselineGetInput {
  /** Name of a baseline, or its file name (with or without .yaml). */
  readonly baseline: string;
  /** Also give, at each entry's version in the baseline, the verification status of each requirement in every view it applies in, except a variant whose status the metamodel marks invalid (SR-047 AK6; only the variant's view when the stored selection has one, also when its status is invalid, SR-094 AK5), and the validation status: own records up to the baseline's date and time, records of that version dated after it named apart (SR-094). Only each requirement's own records count, never indirect evidence (SR-094 AK6): a requirement of the baseline that `evidence.status` gives as `indirect` in a view today, verified through its children, is `open` in that view's row. Like the rest of the output it reads the evidence files on disk, so each repository should be checked out at the commit the baseline names; a `baseline.repository-commit-differs` warning names each one that is not. */
  readonly withEvidence: boolean;
  /** Elements of the page; total counts all. */
  readonly limit: number;
  /** Elements skipped before the page. */
  readonly offset: number;
}

/**
 * Output of `baseline.get`. The elements of a baseline with their version then and its date, each marked changed, superseded, removed or added since (SR-051); with withEvidence also the verification and validation status at their version in the baseline (SR-094).
 * Schema: `schemas/commands/baseline.get.json output`.
 */
export interface BaselineGetOutput {
  /** Name of the baseline. */
  readonly name: string;
  /** Relative to the workspace root, / as separator. */
  readonly file: string;
  /** The repository that holds the file. */
  readonly repository: string;
  readonly date: IsoDateTime;
  /** The view of the stored selection; left out for the core. */
  readonly view?: ViewId;
  /** The file stores a selection. Without it no element is added or removed (SR-051 AK2/AK3). */
  readonly selectionKnown: boolean;
  /** The repositories the baseline names, each with its commit then. */
  readonly repositories: readonly {
    /** Workspace name of the repository. */
    readonly name: string;
    readonly commit: Commit;
  }[];
  /** One page: the file's entries in file order, then the added elements in store order. State precedence: missing or inaccessible, superseded, removed, changed, unchanged; added only for elements not in the file. */
  readonly elements: readonly {
    readonly id: Uuid;
    /** The repository of the copy, whenever it is known. */
    readonly repository?: string;
    /** missing: not in the store, or without repository or with one the workspace does not name and not found. inaccessible: its repository is in the workspace file but not here (D-058, SR-006, incomplete). removed: not superseded and no longer in the stored selection (SR-051 AK3). added: in the stored selection and not in the file. */
    readonly state:
      | "unchanged"
      | "changed"
      | "superseded"
      | "removed"
      | "added"
      | "missing"
      | "inaccessible";
    /** The version in the baseline; left out for added. */
    readonly version?: Version;
    /** Date of that version from the Git history (ADR-0005), read for the page only; null when unknown. */
    readonly versionDate?: string | null;
    /** The current version when it differs, also for removed and added. */
    readonly current?: Version;
    /** With withEvidence, for entries of the file (not added, missing or inaccessible) whose type has the meaning requirement: one row per view it applies in now, the core first, then the variants in store order (SR-094 AK4, SR-047 AK3), none for a variant whose status the metamodel marks invalid now (SR-047 AK6); with a variant in the stored selection only that variant's row, also when its status is invalid (SR-094 AK5, SR-047 AK6). Empty when it applies in no view shown. Own records only, never indirect (SR-094 AK6). Left out when the stored view cannot be resolved. */
    readonly verification?: readonly {
      readonly view: ViewId;
      /** From the records of the view that count for the baseline: dated at or before it (SR-094 AK2); outdated with records of other versions only, open without (SR-094 AK3). */
      readonly status: "open" | "verified" | "failed" | "outdated";
      /** How many acceptance criteria of the version in the baseline these records verify, as for evidence.status (SR-031 AK5): 0 of all of them without a counting record. Left out when that version has no acceptance criteria, and when its criteria cannot be read because it is not the current version and Git does not have it. */
      readonly criteria?: DataExportCriteriaCount;
      /** The records of the baseline version in this view dated after the baseline, newest first: they do not count (SR-094 AK2). Left out when there is none. */
      readonly later?: readonly DataExportEvidenceRecord[];
    }[];
    /** With withEvidence, for entries of the file (not added, missing or inaccessible) of a type with the meaning need and for one with the meaning requirement with a validation record (SR-038 AK5, SR-094 AK7): the status at the baseline version from the validation records that count for the baseline, without view. Open without such records. */
    readonly validation?: ValidationStatus;
    /** With validation `inconclusive`: the `reason` of the record that decides it (SR-172 AK2). */
    readonly validationReason?: string;
    /** With validation: the validation records of the baseline version dated after the baseline, newest first; they do not count (SR-094 AK2). Left out when there is none. */
    readonly validationLater?: readonly DataExportEvidenceRecord[];
  }[];
  /** Elements per state over all pages. */
  readonly counts: {
    /** Elements unchanged since the baseline. */
    readonly unchanged: number;
    /** Elements changed since the baseline. */
    readonly changed: number;
    /** Elements superseded since the baseline. */
    readonly superseded: number;
    /** Elements that left the selection since the baseline. */
    readonly removed: number;
    /** Elements that joined the selection since the baseline. */
    readonly added: number;
    /** Elements of the baseline that are not found. */
    readonly missing: number;
    /** Elements of the baseline in a repository that is not on this machine. */
    readonly inaccessible: number;
  };
  /** Entries of the file plus added elements. */
  readonly total: number;
  /** The elements of the page, the variant of `view` and the variants the verification rows name, each once in the order first named (ThomasBirkmaier/ReqSeq-archive#588). */
  readonly names: readonly ElementName[];
  readonly problems?: readonly Problem[];
  readonly incomplete?: Incomplete;
}

/**
 * Input of `baseline.compare` as `run` gets it: validated, properties with a `default` filled in. The two commits and the Git command that show the difference of an element since a baseline (SR-051 AK4). Runs nothing.
 * Schema: `schemas/commands/baseline.compare.json input`.
 */
export interface BaselineCompareInput {
  /** Name of a baseline, or its file name (with or without .yaml). */
  readonly baseline: string;
  readonly ref: ElementRef;
}

/**
 * Output of `baseline.compare`. The two commits and the Git command that show the difference of an element since a baseline (SR-051 AK4). Runs nothing.
 * Schema: `schemas/commands/baseline.compare.json output`.
 */
export interface BaselineCompareOutput {
  /** Workspace name of the repository of the element. */
  readonly repository: string;
  readonly from: Commit;
  /** The commit to compare with; null for the working copy. */
  readonly to: string | null;
  /** The element file now, relative to its repository. */
  readonly file: string;
  /** Its path at the baseline commit, when the file moved. */
  readonly oldFile?: string;
  /** git -C <repository folder> diff <from> [<to>] -- [<oldFile>] <file>, to run in the workspace root, / as separator, the same on every access. */
  readonly command: readonly string[];
}

/**
 * Input of `reqif.analyze` as `run` gets it: validated, properties with a `default` filled in. Preview the import of a ReqIF file: types, attributes and values without mapping; for a repeated delivery the new, changed and dropped requirements and the conflicts with local changes; the losses. Writes nothing.
 * Schema: `schemas/commands/reqif.analyze.json input`.
 */
export interface ReqifAnalyzeInput {
  readonly file: LocalPath;
  readonly mapping?: LocalPath;
  /** Source name for a file of ReqSeq without mapping; default the header TITLE. */
  readonly source?: string;
}

/**
 * Output of `reqif.analyze`. Preview the import of a ReqIF file: types, attributes and values without mapping; for a repeated delivery the new, changed and dropped requirements and the conflicts with local changes; the losses. Writes nothing.
 * Schema: `schemas/commands/reqif.analyze.json output`.
 */
export interface ReqifAnalyzeOutput {
  readonly unmapped: readonly ReqifUnmapped[];
  /** Objects the import would create as new elements, without UUID. */
  readonly new: readonly ReqifObject[];
  /** Elements of an earlier delivery of the source (same source IDENTIFIER) whose version with the delivery differs from their import version, conflicts included (SR-056 AK1). */
  readonly changed: readonly ReqifObject[];
  /** Elements of the source whose object the file no longer has; the import only lists them (SR-056 AK3). */
  readonly dropped: readonly ReqifObject[];
  /** Changed elements that were also changed locally since their import; reqif.import needs take or keep for each (SR-056 AK4). */
  readonly conflicts: readonly ReqifObject[];
  readonly losses: readonly ReqifLoss[];
  /** Warnings: a title, property or relation the import writes over another value (reqif.replaces-local), a repository not on this machine, an element file that cannot be read. */
  readonly problems?: readonly Problem[];
}

/**
 * Input of `reqif.import` as `run` gets it: validated, properties with a `default` filled in. Import a ReqIF 1.2 file through a saved mapping, all or nothing: one element per object, with the losses reported. A repeated delivery of the same source updates the elements of the earlier one.
 * Schema: `schemas/commands/reqif.import.json input`.
 */
export interface ReqifImportInput {
  readonly file: LocalPath;
  /** Name of the delivery, written to the origin of each element it imports or updates. */
  readonly delivery: string;
  /** Needed unless the file comes from ReqSeq (REQ-IF-TOOL-ID reqseq), which is mapped one to one. */
  readonly mapping?: LocalPath;
  /** Source name for a file of ReqSeq without mapping; default the header TITLE. */
  readonly source?: string;
  /** Conflicts for which the delivery is taken: an exact source IDENTIFIER, else an element among the conflicts. */
  readonly take?: readonly ElementRef[];
  /** Conflicts for which the local element is kept: an exact source IDENTIFIER, else an element among the conflicts. */
  readonly keep?: readonly ElementRef[];
}

/**
 * Output of `reqif.import`. Import a ReqIF 1.2 file through a saved mapping, all or nothing: one element per object, with the losses reported. A repeated delivery of the same source updates the elements of the earlier one.
 * Schema: `schemas/commands/reqif.import.json output`.
 */
export interface ReqifImportOutput {
  /** New elements. */
  readonly created: readonly ReqifObject[];
  /** Elements of an earlier delivery the delivery was written into (changed, taken, or a title, property or relation that differed). */
  readonly updated: readonly ReqifObject[];
  /** Conflicts in keep: content left, only the origin written. */
  readonly kept: readonly ReqifObject[];
  /** Elements of the source whose object the file no longer has; not changed. */
  readonly dropped: readonly ReqifObject[];
  readonly losses: readonly ReqifLoss[];
  readonly files: readonly string[];
  readonly problems?: readonly Problem[];
}

/**
 * Input of `reqif.saveMapping` as `run` gets it: validated, properties with a `default` filled in. Save or change the mapping of a source to the own metamodel, in the mapping folder (default `reqif`).
 * Schema: `schemas/commands/reqif.saveMapping.json input`.
 */
export interface ReqifSaveMappingInput {
  readonly mapping: ReqifMappingFileWithDefaults;
  /** Inside the mapping folder of the workspace, for every access; default the portable source name. */
  readonly file?: LocalPath;
}

/**
 * Output of `reqif.saveMapping`. Save or change the mapping of a source to the own metamodel, in the mapping folder (default `reqif`).
 * Schema: `schemas/commands/reqif.saveMapping.json output`.
 */
export interface ReqifSaveMappingOutput {
  readonly files: readonly string[];
  readonly problems?: readonly Problem[];
}

/**
 * Input of `reqif.export` as `run` gets it: validated, properties with a `default` filled in. Export a selection or a saved export profile, or with statements the elements of the mapping's source, as ReqIF 1.2: IDENTIFIER `_` plus the UUID (the source IDENTIFIER for statements), text as XHTML and as `reqseq-markdown`, relations as SPEC-RELATIONs, targets outside the export as stubs.
 * Schema: `schemas/commands/reqif.export.json input`.
 */
export interface ReqifExportInput {
  readonly output: LocalPath;
  readonly selection?: ElementSelection;
  /** Name of a saved export profile of the mapping. Not taken yet: it gives `input.invalid`. */
  readonly profile?: string;
  readonly mapping?: LocalPath;
  /** Added to the omitted properties of the mapping and the profile; with mapping, saved in it for later deliveries. */
  readonly omitProperties?: readonly Key[];
  /** Export the elements of the mapping's source with their statements, back to that source; needs `mapping`. */
  readonly statements?: boolean;
}

/**
 * Output of `reqif.export`. Export a selection or a saved export profile, or with statements the elements of the mapping's source, as ReqIF 1.2: IDENTIFIER `_` plus the UUID (the source IDENTIFIER for statements), text as XHTML and as `reqseq-markdown`, relations as SPEC-RELATIONs, targets outside the export as stubs.
 * Schema: `schemas/commands/reqif.export.json output`.
 */
export interface ReqifExportOutput {
  /** The written ReqIF file, relative to the workspace root when it lies inside, else absolute. */
  readonly file: string;
  /** Exported elements. */
  readonly elements: number;
  /** Exported relations. */
  readonly relations: number;
  /** With statements: exported elements without a statement. */
  readonly withoutStatement?: number;
  readonly files?: readonly string[];
  readonly problems?: readonly Problem[];
}

/** Input and output type of every catalog command, by name (`defineCommand` in catalog.ts). */
export interface CommandTypes {
  readonly "workspace.init": { readonly input: WorkspaceInitInput; readonly output: WorkspaceInitOutput };
  readonly "workspace.status": { readonly input: WorkspaceStatusInput; readonly output: WorkspaceStatusOutput };
  readonly "workspace.check": { readonly input: WorkspaceCheckInput; readonly output: WorkspaceCheckOutput };
  readonly "workspace.activity": { readonly input: WorkspaceActivityInput; readonly output: WorkspaceActivityOutput };
  readonly "workspace.recent": { readonly input: WorkspaceRecentInput; readonly output: WorkspaceRecentOutput };
  readonly "workspace.listFolder": { readonly input: WorkspaceListFolderInput; readonly output: WorkspaceListFolderOutput };
  readonly "tool.info": { readonly input: ToolInfoInput; readonly output: ToolInfoOutput };
  readonly "metamodel.get": { readonly input: MetamodelGetInput; readonly output: MetamodelGetOutput };
  readonly "element.create": { readonly input: ElementCreateInput; readonly output: ElementCreateOutput };
  readonly "element.get": { readonly input: ElementGetInput; readonly output: ElementGetOutput };
  readonly "element.resolve": { readonly input: ElementResolveInput; readonly output: ElementResolveOutput };
  readonly "element.list": { readonly input: ElementListInput; readonly output: ElementListOutput };
  readonly "element.facets": { readonly input: ElementFacetsInput; readonly output: ElementFacetsOutput };
  readonly "element.update": { readonly input: ElementUpdateInput; readonly output: ElementUpdateOutput };
  readonly "element.setStatus": { readonly input: ElementSetStatusInput; readonly output: ElementSetStatusOutput };
  readonly "element.supersede": { readonly input: ElementSupersedeInput; readonly output: ElementSupersedeOutput };
  readonly "element.bulkUpdate": { readonly input: ElementBulkUpdateInput; readonly output: ElementBulkUpdateOutput };
  readonly "element.addAttachment": { readonly input: ElementAddAttachmentInput; readonly output: ElementAddAttachmentOutput };
  readonly "relation.options": { readonly input: RelationOptionsInput; readonly output: RelationOptionsOutput };
  readonly "relation.add": { readonly input: RelationAddInput; readonly output: RelationAddOutput };
  readonly "relation.remove": { readonly input: RelationRemoveInput; readonly output: RelationRemoveOutput };
  readonly "trace.chain": { readonly input: TraceChainInput; readonly output: TraceChainOutput };
  readonly "trace.related": { readonly input: TraceRelatedInput; readonly output: TraceRelatedOutput };
  readonly "trace.affected": { readonly input: TraceAffectedInput; readonly output: TraceAffectedOutput };
  readonly "trace.neighbourhood": { readonly input: TraceNeighbourhoodInput; readonly output: TraceNeighbourhoodOutput };
  readonly "trace.matrix": { readonly input: TraceMatrixInput; readonly output: TraceMatrixOutput };
  readonly "trace.graph": { readonly input: TraceGraphInput; readonly output: TraceGraphOutput };
  readonly "hint.list": { readonly input: HintListInput; readonly output: HintListOutput };
  readonly "hint.confirm": { readonly input: HintConfirmInput; readonly output: HintConfirmOutput };
  readonly "element.search": { readonly input: ElementSearchInput; readonly output: ElementSearchOutput };
  readonly "filter.list": { readonly input: FilterListInput; readonly output: FilterListOutput };
  readonly "filter.save": { readonly input: FilterSaveInput; readonly output: FilterSaveOutput };
  readonly "evidence.list": { readonly input: EvidenceListInput; readonly output: EvidenceListOutput };
  readonly "evidence.record": { readonly input: EvidenceRecordInput; readonly output: EvidenceRecordOutput };
  readonly "evidence.enrichJunit": { readonly input: EvidenceEnrichJunitInput; readonly output: EvidenceEnrichJunitOutput };
  readonly "evidence.status": { readonly input: EvidenceStatusInput; readonly output: EvidenceStatusOutput };
  readonly "evidence.coverage": { readonly input: EvidenceCoverageInput; readonly output: EvidenceCoverageOutput };
  readonly "evidence.degree": { readonly input: EvidenceDegreeInput; readonly output: EvidenceDegreeOutput };
  readonly "evidence.withoutPassedTest": { readonly input: EvidenceWithoutPassedTestInput; readonly output: EvidenceWithoutPassedTestOutput };
  readonly "data.export": { readonly input: DataExportInput; readonly output: DataExportOutput };
  readonly "data.store": { readonly input: DataStoreInput; readonly output: DataStoreOutput };
  readonly "variant.diff": { readonly input: VariantDiffInput; readonly output: VariantDiffOutput };
  readonly "variant.exclude": { readonly input: VariantExcludeInput; readonly output: VariantExcludeOutput };
  readonly "baseline.create": { readonly input: BaselineCreateInput; readonly output: BaselineCreateOutput };
  readonly "baseline.list": { readonly input: BaselineListInput; readonly output: BaselineListOutput };
  readonly "baseline.get": { readonly input: BaselineGetInput; readonly output: BaselineGetOutput };
  readonly "baseline.compare": { readonly input: BaselineCompareInput; readonly output: BaselineCompareOutput };
  readonly "reqif.analyze": { readonly input: ReqifAnalyzeInput; readonly output: ReqifAnalyzeOutput };
  readonly "reqif.import": { readonly input: ReqifImportInput; readonly output: ReqifImportOutput };
  readonly "reqif.saveMapping": { readonly input: ReqifSaveMappingInput; readonly output: ReqifSaveMappingOutput };
  readonly "reqif.export": { readonly input: ReqifExportInput; readonly output: ReqifExportOutput };
}
